use super::{
    Unstructured, harvest_declared_gc_facts, simplify_lowered_graph_expanding,
    tyref_to_attr_value_type_with,
};

/// Per-graph simplification after lowering — the model-layer slice of
/// RPython `simplify_graph(graph)` (`simplify.py`), which
/// upstream runs on every freshly built flow graph.  Only the passes
/// the Abort → `RaiseImplicit` fold needs are wired:
///
/// - `eliminate_empty_blocks` (simplify.py) collapses the empty
///   raise block between a discriminant switch's `else
///   unreachable!()` exit and `exceptblock`, exposing the
///   `[Constant(AssertionError), …]` link to the next pass.
/// - `retarget_assert_raise_blocks` points an edge into a bare
///   implicit-raise block at `exceptblock` instead, which is where
///   upstream's flow space puts it and what the next pass matches.
/// - `remove_assertion_errors` (simplify.py) prunes the
///   shouldn't-occur branch and promotes the surviving exit to an
///   unconditional link.
/// - `prune_dead_phis` (`transform_dead_op_vars`, simplify.py)
///   melts the now-dead condition ops — the `__discriminant`
///   FieldRead feeding the dropped exitswitch
///   (`removeassert.py` `remove_asserts` "now melt away the (hopefully) dead
///   operation that compute the condition").  Upstream leaves this to
///   the later backendopt sweep (`backendopt/all.py`); the model
///   layer has no later sweep, so it runs here — see `sweep_dead_vars`
///   below for when.
///
/// `sweep_dead_vars` selects which of the two call sites this is.  The
/// end-of-lowering call passes `true` and runs `prune_dead_phis`
/// unconditionally, as `all_passes` does.  The result-exc pre-pass passes
/// `false`: `rewire_result_exc_call_sites` walks the `Result` diamond by
/// following one `Variable` identity from link args into the target's
/// inputargs, and a `Result` that is dead downstream is exactly what the
/// sweep removes — the walk then fails the whole graph with "block N's exit
/// does not carry the tracked value".  Measured: three `_io` `__init__`
/// graphs stopped lowering, taking the `reader_reset_buf` /
/// `writer_reset_buf` callees they queue with them.  The pre-pass is
/// pyre-only and exists so the diamond matcher sees a pruned discriminant
/// switch; keeping the sweep out of it leaves one sweep per graph, which is
/// what upstream has.
fn simplify_lowered_graph(
    graph: &mut FunctionGraph,
    struct_field_attrs: &std::collections::HashMap<String, Vec<(String, ValueType)>>,
    sweep_dead_vars: bool,
    guard_words: &std::collections::HashSet<Variable>,
) {
    simplify_lowered_graph_expanding(
        graph,
        struct_field_attrs,
        sweep_dead_vars,
        guard_words,
        &|_, _| None,
    )
    .expect("inline-struct expansion is off");
}

/// Classify a struct field [`TyRef`] into the RPython `lltype` register
/// class the annotator pre-fills into `FORCE_ATTRIBUTES_INTO_CLASSES`.
///
/// Like [`tyref_to_value_type`], this keeps the signed/unsigned split:
/// `{"Scalar": {"Integer": {"Unsigned": …}}}` shells to [`ValueType::Unsigned`] so
/// `valuetype_to_someshell`
/// picks `SomeInteger { unsigned: true }`, matching the per-field shells
/// the syn classifier produced for `u8`..`usize`.  `char` and every
/// signed width fold to `Int`; `bool`/`float` keep their classes; a
/// payload-carrying enum paints `Ref(Some(root))` so the FORCE-attr intern
/// keys the same classdef `Input.class_root` does; every other non-scalar
/// shape (named struct, reference, raw pointer, tuple, slice, array,
/// `Box`/`Rc`/`Arc` wrapper) folds to `Ref(None)` whose someshell ignores
/// the payload. A `repr(transparent)` scalar wrapper keeps its inner register
/// class, as it does at ordinary value sites.
fn tyref_to_attr_value_type(ty: &TyRef, llbc: &Llbc) -> ValueType {
    let gc_struct_ids = harvest_declared_gc_facts(llbc).gc_struct_ids();
    let raw_alloc_flavor_structs =
        crate::front::llbc_hints::harvest_alloc_flavor_raw_from_llbcs(std::slice::from_ref(llbc));
    tyref_to_attr_value_type_with(
        ty,
        llbc,
        no_tombstoned_leaves(),
        &gc_struct_ids,
        &raw_alloc_flavor_structs,
    )
}

impl<'b> super::MovedOutLocals<'b> {
    /// A fixed answer for `body`, so a test can state the move set.
    fn with_set(body: &'b Unstructured, set: bit_set::BitSet) -> Self {
        Self {
            body,
            llbc: None,
            set: std::cell::OnceCell::from(set),
        }
    }
}

mod reachable_mask_tests {
    use super::super::{forward_reachable_mask, lowered_reachable_mask, successor_blocks};
    use majit_charon_reader::{Llbc, ullbc::Unstructured};
    use serde_json::{Value, json};

    fn span() -> Value {
        json!({
            "data": {
                "file_id": 0,
                "beg": {"line": 0, "col": 0},
                "end": {"line": 0, "col": 0}
            },
            "generated_from_span": null
        })
    }

    fn ty() -> Value {
        json!({"Deduplicated": 0})
    }

    fn place(i: u64) -> Value {
        json!({"kind": {"Local": i}, "ty": ty()})
    }

    fn bb(kind: Value, is_cleanup: bool) -> Value {
        let unwind = if is_cleanup { "Cleanup" } else { "Regular" };
        json!({
            "statements": [],
            "terminator": {"span": span(), "kind": kind},
            "kind": unwind
        })
    }

    fn body_of(blocks: Vec<Value>) -> (Llbc, Unstructured) {
        let llbc = Llbc::from_slice(
            br#"{"charon_version":"t","has_errors":false,"translated":{"crate_name":"c","fun_decls":[]}}"#,
        )
        .expect("empty artefact");
        let raw = json!({
            "span": span(),
            "locals": {
                "arg_count": 0,
                "locals": [{"index": 0, "name": null, "span": span(), "ty": ty()}]
            },
            "body": blocks
        });
        let body: Unstructured = serde_json::from_value(raw).expect("fixture body");
        (llbc, body)
    }

    /// A one-arm `Ref` SwitchInt is niche-shaped; the panic default is a
    /// successor the lowered mask keeps.
    #[test]
    fn lowered_mask_keeps_niche_option_panic_default() {
        let switch = json!({"Switch": {
            "discr": {"Copy": place(0)},
            "targets": {"SwitchInt": [
                null,
                [[{"Ref": [{"Body": 18}, {"DynTrait": {"id": 0}}, "Mut"]}, 1]],
                2
            ]}
        }});
        let (llbc, body) = body_of(vec![
            bb(switch, false),
            bb(json!("Return"), false),
            bb(json!({"Abort": "UndefinedBehavior"}), false),
        ]);
        let lowered = lowered_reachable_mask(&llbc, &body);
        assert_eq!(
            lowered,
            vec![true, true, true],
            "niche Option panic default is an emitted If arm"
        );
        let forward = forward_reachable_mask(&llbc, &body);
        assert_eq!(forward, vec![true, true, true]);
    }

    /// Arms {0, 1} plus a panic default sit outside the niche shape, so
    /// the lowered mask drops that default.
    #[test]
    fn lowered_mask_drops_generic_switchint_panic_default() {
        let switch = json!({"Switch": {
            "discr": {"Copy": place(0)},
            "targets": {"SwitchInt": [
                null,
                [
                    [{"Scalar": {"Unsigned": ["U8", "0"]}}, 1],
                    [{"Scalar": {"Unsigned": ["U8", "1"]}}, 1]
                ],
                2
            ]}
        }});
        let (llbc, body) = body_of(vec![
            bb(switch, false),
            bb(json!("Return"), false),
            bb(json!({"Abort": "UndefinedBehavior"}), false),
        ]);
        let lowered = lowered_reachable_mask(&llbc, &body);
        assert_eq!(
            lowered,
            vec![true, true, false],
            "SwitchInt arms {{0, 1}} leave the panic default off the lowered mask"
        );
    }

    /// `strip_cleanup_blocks` left bodies unchanged when a normal successor
    /// targets a cleanup block (`kept_block_normal_successor_is_cleanup`).
    #[test]
    fn successor_blocks_keeps_a_normal_edge_into_cleanup() {
        let (llbc, body) = body_of(vec![
            bb(json!({"Goto": {"target": 1}}), false),
            bb(json!("UnwindResume"), true),
        ]);
        let succs = successor_blocks(&llbc, &body, 0, false);
        assert_eq!(succs, vec![1]);
    }
}

mod slice_or_vec_container_root_spelling_tests {
    use super::super::slice_or_vec_container_root_spelling;

    #[test]
    fn slice_and_vec_spellings_are_list_residuals() {
        assert_eq!(slice_or_vec_container_root_spelling("&[u8]"), None);
        assert_eq!(
            slice_or_vec_container_root_spelling("&mut [u8]"),
            Some("&mut [u8]")
        );
        assert_eq!(
            slice_or_vec_container_root_spelling("*mut [u8]"),
            Some("*mut [u8]")
        );
        assert_eq!(
            slice_or_vec_container_root_spelling("*mut Vec<Utf8LocElem>"),
            Some("*mut Vec<Utf8LocElem>")
        );
        assert_eq!(
            slice_or_vec_container_root_spelling("Vec<u8>"),
            Some("Vec<u8>")
        );
        assert_eq!(
            slice_or_vec_container_root_spelling("*mut Vec<*mut u8>"),
            Some("*mut Vec<*mut u8>")
        );
        assert_eq!(
            slice_or_vec_container_root_spelling("Vec<*mut u8>"),
            Some("Vec<*mut u8>")
        );
        assert_eq!(
            slice_or_vec_container_root_spelling("*mut Vec<usize>"),
            Some("*mut Vec<usize>")
        );
        assert_eq!(slice_or_vec_container_root_spelling("&Engine"), None);
        assert_eq!(slice_or_vec_container_root_spelling("*mut PyObject"), None);
        assert_eq!(slice_or_vec_container_root_spelling("[u8; 4]"), None);
        assert_eq!(slice_or_vec_container_root_spelling("*mut [u8; 4]"), None);
        assert_eq!(slice_or_vec_container_root_spelling("&[u8; 4]"), None);
    }
}

mod f64_bitcast_path_tests {
    use super::super::path_ends_with_segments;

    #[test]
    fn f64_bit_casts_are_path_suffixes_not_substrings() {
        let cases = [
            (
                "from_bits_core",
                "core::f64::<Impl>::from_bits",
                "f64::<Impl>::from_bits",
                true,
            ),
            (
                "from_bits_std",
                "std::f64::<Impl>::from_bits",
                "f64::<Impl>::from_bits",
                true,
            ),
            (
                "from_bits_position",
                "rhai::grain::vm::jit::position_from_bits",
                "f64::<Impl>::from_bits",
                false,
            ),
            (
                "from_bits_step_flags",
                "rhai::grain::format::StepFlags::<Impl>::from_bits",
                "f64::<Impl>::from_bits",
                false,
            ),
            (
                "to_bits_core",
                "core::f64::<Impl>::to_bits",
                "f64::<Impl>::to_bits",
                true,
            ),
            (
                "to_bits_position",
                "some_host::position_to_bits",
                "f64::<Impl>::to_bits",
                false,
            ),
        ];
        for (name, path, suffix, want) in cases {
            assert_eq!(path_ends_with_segments(path, suffix), want, "case {name}");
        }
    }
}

#[test]
fn int_cast_action_narrows_inside_the_64_bit_int_box() {
    // `int_or_float_decode_int`: `value as u32 as i32 as i64`. With a
    // 32-bit `usize` (wasm32) the first two steps still narrow inside
    // the Int box.
    assert_eq!(
        super::int_cast_action(64, false, 32, true),
        Some(super::IntCastAction::And(0xffff_ffff))
    );
    assert_eq!(
        super::int_cast_action(32, true, 32, false),
        Some(super::IntCastAction::SignExt(4))
    );
    assert_eq!(
        super::int_cast_action(32, false, 64, false),
        Some(super::IntCastAction::Alias)
    );
    assert_eq!(
        super::int_cast_action(32, true, 64, false),
        Some(super::IntCastAction::IntMask)
    );
    assert_eq!(
        super::int_cast_action(64, false, 64, true),
        Some(super::IntCastAction::RUint)
    );
    assert_eq!(super::int_cast_action(128, false, 64, false), None);
}

/// Widening integer storage keeps every address bit (`rbuiltin.py` `gen_cast`).
#[test]
fn int_scalar_width_covers_word_accepts_widening_integer() {
    assert!(super::int_scalar_width_covers_word("U64", 8));
    assert!(super::int_scalar_width_covers_word("I64", 8));
    assert!(super::int_scalar_width_covers_word("U128", 8));
    assert!(!super::int_scalar_width_covers_word("U32", 8));
    assert!(super::int_scalar_width_covers_word("U64", 4));
    assert!(super::int_scalar_width_covers_word("U32", 4));
    assert!(!super::int_scalar_width_covers_word("U16", 4));
}

/// `Isize`/`Usize` truncate to the target word (`lltype.py` `cast_primitive`).
#[test]
fn const_cast_int_with_word_truncates_isize_usize_to_target_width() {
    let usize_ty = serde_json::json!({"Integer": {"Unsigned": "Usize"}});
    let isize_ty = serde_json::json!({"Integer": {"Signed": "Isize"}});
    assert_eq!(
        super::const_cast_int_with_word(0x1_0000_0001, &usize_ty, 8),
        Some(0x1_0000_0001)
    );
    assert_eq!(
        super::const_cast_int_with_word(0xffff_ffff, &isize_ty, 8),
        Some(0xffff_ffff)
    );
    assert_eq!(
        super::const_cast_int_with_word(0x1_0000_0001, &usize_ty, 4),
        Some(1)
    );
    assert_eq!(
        super::const_cast_int_with_word(0xffff_ffff, &isize_ty, 4),
        Some(-1)
    );
}

/// A missing Charon layout on `GcEntries { length: usize, items: [T; 0] }`
/// still has to place items at the length word rounded up to `T`'s
/// alignment (`array_items_base`). A 4-byte wasm32 word and an 8-aligned
/// `Entry<i64, PyObjectRef>` therefore sit at 8, not 4; a 64-bit word
/// already satisfies that alignment.
#[test]
fn array_field_tail_offset_rounds_length_word_to_element_align() {
    assert_eq!(
        super::Lowering::array_field_tail_offset_fallback(4, Some(8)),
        Some(8)
    );
    assert_eq!(
        super::Lowering::array_field_tail_offset_fallback(8, Some(8)),
        Some(8)
    );
    assert_eq!(
        super::Lowering::array_field_tail_offset_fallback(4, None),
        None
    );
}

/// `get_array_token` uses the actual array type. An 8-aligned source
/// tail must not pick up a 16-aligned `.cast()` dest.
#[test]
fn array_tail_elem_align_prefers_source_array_over_cast_dest() {
    assert_eq!(
        super::Lowering::array_tail_instantiated_elem_align(Some(8), None, Some(16)),
        Some(8)
    );
    assert_eq!(
        super::Lowering::array_tail_instantiated_elem_align(None, Some(8), Some(16)),
        Some(8)
    );
    assert_eq!(
        super::Lowering::array_tail_instantiated_elem_align(None, None, Some(8)),
        Some(8)
    );
}

/// `direct_arrayitems` constructs a pointer to item zero. Unknown
/// items offset stops translation rather than emit a different op.
#[test]
fn unknown_array_items_offset_stops_direct_arrayitems() {
    let err = super::Lowering::array_field_items_offset(None, "GcEntries", "items")
        .expect_err("unknown items offset must stop translation");
    assert!(err.to_string().contains("direct_arrayitems"), "{err}");
    assert_eq!(
        super::Lowering::array_field_items_offset(Some(8), "GcEntries", "items").unwrap(),
        8
    );
}

/// `entries_item_ptr` of `GcEntries<i64, PyObjectRef>` is
/// `addr_of_mut!((*header).items).cast()`. The generic `GcEntries`
/// declaration has no Charon layout and unresolved type variables,
/// so the items offset is the length word rounded up to the
/// instantiated `Entry` alignment (`array_items_base`). `Entry`
/// always contains `f_hash: u64`, so that offset is 8.
#[test]
fn entries_item_ptr_gcentries_i64_gcref_items_offset_is_8() {
    use crate::model::{CallTarget, OpKind};
    let path = crate::runtime_names::artifacts::OBJECT_ULLBC;
    let llbc = Llbc::load(path).expect("load pyre-object LLBC");
    let name_path = "pyre_object::rordereddict_entries::entries_item_ptr";
    let fd = llbc
        .iter_local_fns()
        .find(|fd| fd.item_meta.name_path() == name_path)
        .unwrap_or_else(|| panic!("{name_path} in pyre-object LLBC"));
    let gcref_id = llbc
        .iter_type_decls()
        .find(|td| td.item_meta.name_path() == "pyre_object::pyobject::PyObject")
        .unwrap_or_else(|| panic!("PyObject in pyre-object LLBC"))
        .def_id;
    let i64_ty = serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}});
    let gcref_ty = serde_json::json!({
        "RawPtr": [
            {
                "Adt": {
                    "id": gcref_id,
                    "generics": {
                        "regions": [],
                        "types": [],
                        "const_generics": [],
                        "trait_refs": []
                    },
                    "builtin": null
                }
            },
            "Mut"
        ]
    });
    let body = crate::front::clause_spec::substituted_unstructured(
        fd,
        &llbc,
        &[],
        &[i64_ty, gcref_ty],
        &[],
    )
    .expect("substituted entries_item_ptr body");
    let context = super::LowerContext::new(&llbc);
    let struct_fields = super::struct_field_registry_from_rows(&context.struct_fields);
    let accum = super::AccumulatorFacts::build(&llbc, &body);
    let jitdriver_receiver_roots =
        crate::codewriter::jtransform::default_jitdriver_receiver_roots();
    let graph = super::lower_unstructured_with_static_addrs_and_attrs(
        &llbc,
        fd,
        &body,
        crate::HostStaticAddrs::default(),
        &jitdriver_receiver_roots,
        &context.struct_field_attrs,
        &struct_fields,
        &context.dont_look_inside,
        &context.tombstoned_leaves,
        &context.gc_struct_ids,
        &context.immutable_fields,
        &context.raw_alloc_flavor_structs,
        accum.has_builder,
        &accum,
        &super::RootStackAnalyzer::new(&llbc, &super::RootStackState::new(&llbc)),
        None,
        true,
        None,
    )
    .unwrap_or_else(|err| panic!("lower substituted {name_path}: {err:?}"));

    // `emit_array_tail_item_ptr` is `cast_ptr_to_int` + ConstInt(offset)
    // + add + `cast_int_to_ptr`. The address-taken `items` FieldRead is
    // unused after that rewrite and may be dropped.
    let mut offset = None;
    let mut saw_cast_int_to_ptr = false;
    for block in &graph.blocks {
        for (i, op) in block.operations.iter().enumerate() {
            if let OpKind::ConstInt(n) = op.kind {
                let add = block.operations.get(i + 1).map(|next| &next.kind);
                if matches!(
                    add,
                    Some(OpKind::BinOp { op, .. }) if op == "add"
                ) {
                    offset = Some(n);
                }
            }
            if let OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                ..
            } = &op.kind
                && segments.last().is_some_and(|s| s == "cast_int_to_ptr")
            {
                saw_cast_int_to_ptr = true;
            }
        }
    }
    assert!(
        saw_cast_int_to_ptr,
        "substituted entries_item_ptr must emit direct_arrayitems (cast_int_to_ptr)"
    );
    assert_eq!(
        offset,
        Some(8),
        "GcEntries items sit at the length word rounded up to Entry alignment"
    );
}

/// The unsubstituted generic `entries_item_ptr` has TypeVars and no
/// Charon layout. Translation stops rather than guess the items
/// offset (`array_field_items_offset`).
#[test]
fn unsubstituted_entries_item_ptr_stops_without_guessing_offset() {
    let path = crate::runtime_names::artifacts::OBJECT_ULLBC;
    let llbc = Llbc::load(path).expect("load pyre-object LLBC");
    let err = super::lower_function(&llbc, "entries_item_ptr")
        .expect_err("generic entries_item_ptr has no items offset");
    assert!(err.to_string().contains("direct_arrayitems"), "{err}");
}

/// A one-word-item Vec header pointer is int-banked, matching
/// `descr.py get_type_flag` of a raw Ptr and `rrustvec.rs rust_vec_lltype`.
#[test]
fn rust_vec_header_pointer_tuple_field_is_int_banked() {
    use crate::model::ValueType;
    for spelling in ["*mut Vec<usize>", "*mut Vec<*mut u8>", "*mut Vec<f64>"] {
        assert_eq!(
            super::tuple_field_value_type(spelling),
            ValueType::Int,
            "{spelling}"
        );
    }
}

/// `history.py` `getkind` of a raw `Ptr` to a non-byte primitive is
/// `'int'`. A byte pointer stays `Ref` (GC erasure to `*mut u8`).
#[test]
fn raw_scalar_pointer_tuple_field_is_int_banked() {
    use crate::model::ValueType;
    for spelling in ["*mut usize", "*const usize", "*mut i64", "*mut f64"] {
        assert_eq!(
            super::tuple_field_value_type(spelling),
            ValueType::Int,
            "{spelling}"
        );
    }
    for spelling in ["*mut u8", "*const u8", "*mut *mut usize"] {
        assert_eq!(
            super::tuple_field_value_type(spelling),
            ValueType::Ref(None),
            "{spelling}"
        );
    }
}

