/// `inline_vec_field_part` emits the component read from the SSI
/// local (`ssa.py` `SSA_to_SSI`), not the dominating producer.
#[test]
fn inline_vec_field_part_uses_ssi_local_as_field_read_base() {
    let mut graph = FunctionGraph::new("inline_vec_ssi_base");
    let pred = graph.startblock;
    let target = graph.create_block();
    let base = graph
        .push_op_var(
            pred,
            OpKind::Input {
                name: "holder".into(),
                ty: ValueType::Ref(Some("Holder".into())),
                class_root: None,
            },
            true,
        )
        .unwrap();
    let vec_var = graph.alloc_value_var();
    graph.block_mut(pred).operations.push(SpaceOperation {
        result: Some(vec_var.clone()),
        kind: OpKind::FieldRead {
            base: base.clone(),
            field: FieldDescriptor::new("items", Some("Holder".into())).with_inline_vec(true),
            ty: ValueType::Ref(None),
            pure: true,
        },
    });
    graph.set_goto(pred, target, vec![]);

    let len = super::inline_vec_field_part(
        &mut graph,
        target,
        &vec_var,
        VecFieldPart::Len,
        ValueType::Int,
    )
    .expect("inline vec len read");
    let op = graph
        .block(target)
        .operations
        .iter()
        .find(|op| op.result.as_ref() == Some(&len))
        .expect("len FieldRead");
    match &op.kind {
        OpKind::FieldRead {
            base: read_base, ..
        } => {
            assert!(
                graph.variable_defined_in_block(target, read_base),
                "component read base is defined in the use block"
            );
            assert_ne!(
                read_base.id(),
                base.id(),
                "component read does not bind the dominating producer"
            );
        }
        other => panic!("expected FieldRead, got {other:?}"),
    }
}

/// `dyn_receiver_data_word` emits FatData from the SSI local, not the
/// dominating producer (`ssa.py` `SSA_to_SSI`).
#[test]
fn dyn_receiver_data_word_uses_ssi_local_as_field_read_base() {
    let mut graph = FunctionGraph::new("dyn_receiver_ssi_base");
    let pred = graph.startblock;
    let target = graph.create_block();
    let base = graph
        .push_op_var(
            pred,
            OpKind::Input {
                name: "strategy".into(),
                ty: ValueType::Ref(Some("Strategy".into())),
                class_root: None,
            },
            true,
        )
        .unwrap();
    let recv = graph.alloc_value_var();
    graph.block_mut(pred).operations.push(SpaceOperation {
        result: Some(recv.clone()),
        kind: OpKind::FieldRead {
            base: base.clone(),
            field: FieldDescriptor::new("imp", Some("Strategy".into()))
                .with_vec_part(VecFieldPart::FatMeta),
            ty: ValueType::Int,
            pure: true,
        },
    });
    graph.set_goto(pred, target, vec![]);

    let data =
        super::emit_dyn_receiver_data_word(&mut graph, target, &recv).expect("fat data word");
    let op = graph
        .block(target)
        .operations
        .iter()
        .find(|op| op.result.as_ref() == Some(&data))
        .expect("FatData FieldRead");
    match &op.kind {
        OpKind::FieldRead {
            base: read_base, ..
        } => {
            assert!(
                graph.variable_defined_in_block(target, read_base),
                "FatData read base is defined in the use block"
            );
            assert_ne!(
                read_base.id(),
                base.id(),
                "FatData read does not bind the dominating producer"
            );
        }
        other => panic!("expected FieldRead, got {other:?}"),
    }
}

/// View `.len()` must not put a predecessor Variable on a consumer
/// link (`FrameState.getoutputargs`, `checkgraph` `definevar`).
#[test]
fn array_view_len_link_operand_is_defined_in_the_consumer_block() {
    let mut graph = FunctionGraph::new("array_view_len_consumer");
    let pred = graph.startblock;
    let consumer = graph.create_block();
    let len_var = graph.alloc_value_var_with_type(crate::model::ConcreteType::Unknown);
    graph.block_mut(pred).operations.push(SpaceOperation {
        result: Some(len_var.clone()),
        kind: OpKind::ConstInt(3),
    });
    graph.set_goto(pred, consumer, vec![]);

    assert!(
        !graph.variable_defined_in_block(consumer, &len_var),
        "predecessor length is not a definition in the consumer"
    );
    let bound = super::bind_array_view_len_in_block(&mut graph, consumer, len_var.clone());
    assert_ne!(
        bound.id(),
        len_var.id(),
        "consumer must not name the predecessor Variable on a link"
    );
    assert!(
        graph.variable_defined_in_block(consumer, &bound),
        "same_as result is defined in the consumer (`checkgraph` definevar)"
    );
    match graph.block(consumer).operations.last().map(|op| &op.kind) {
        Some(OpKind::UnaryOp { op, operand, .. }) if op == "same_as" => {
            assert_eq!(operand.id(), len_var.id());
        }
        other => panic!("expected same_as of the predecessor length, got {other:?}"),
    }
    graph.set_return(consumer, Some(bound.clone()));
    match graph.block(consumer).exits[0].args.as_slice() {
        [LinkArg::Value(v)] => {
            assert!(
                graph.variable_defined_in_block(consumer, v),
                "return link operand is defined in the source block"
            );
            assert_eq!(v.id(), bound.id());
        }
        other => panic!("expected one return value, got {other:?}"),
    }
    let same = super::bind_array_view_len_in_block(&mut graph, pred, len_var.clone());
    assert_eq!(
        same.id(),
        len_var.id(),
        "a length already defined in the block is reused"
    );
}

use majit_charon_reader::{
    Llbc,
    ullbc::{NameSeg, TyRef},
};

fn fixture_llbc() -> Llbc {
    Llbc::from_slice(
            br#"{"charon_version":"t","has_errors":false,"translated":{"crate_name":"c","fun_decls":[]}}"#,
        )
        .expect("empty artefact")
}

fn empty_llbc() -> Llbc {
    Llbc::from_slice(
            br#"{"charon_version":"t","has_errors":false,"translated":{"crate_name":"c","fun_decls":[],"files":[]}}"#,
        )
        .expect("empty llbc")
}

fn literal_i64() -> TyRef {
    serde_json::from_value(serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}})).unwrap()
}

fn shared_i64() -> TyRef {
    serde_json::from_value(
            serde_json::json!({"Ref": ["Erased", {"Scalar": {"Integer": {"Signed": "I64"}}}, "Shared"]}),
        )
        .unwrap()
}

fn shared_of(pointee: serde_json::Value) -> TyRef {
    TyRef::Other(serde_json::json!({"Ref": ["Erased", pointee, "Shared"]}))
}

/// `PartialOrd<&B> for &A` formals are `&&T`. One-level
/// `tyref_scalar_pointee_value_type` declines a pointer-to-pointer;
/// `input_param_value_type` peels to the scalar so mergeinputargs
/// sees Integer ∪ Integer (or Float ∪ Float).
#[test]
fn input_param_peels_nested_ref_of_primitive_to_the_scalar() {
    use crate::model::ValueType;
    let llbc = fixture_llbc();
    let i64_ty = serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}});
    let f64_ty = serde_json::json!({"Scalar": {"Float": "F64"}});
    let char_ty = serde_json::json!({"Scalar": "Char"});
    let one = shared_of(i64_ty.clone());
    let two = shared_of(serde_json::json!({"Ref": ["Erased", i64_ty.clone(), "Shared"]}));
    let two_f64 = shared_of(serde_json::json!({"Ref": ["Erased", f64_ty, "Shared"]}));
    let two_char = shared_of(serde_json::json!({"Ref": ["Erased", char_ty, "Shared"]}));
    let range = shared_of(serde_json::json!({"Adt": {"id": 0}}));
    let no_tombstones = std::collections::HashSet::new();
    assert_eq!(
        super::input_param_value_type(
            ValueType::Ref(None),
            &one,
            &llbc,
            false,
            false,
            &no_tombstones
        ),
        ValueType::Int
    );
    assert_eq!(
        super::input_param_value_type(
            ValueType::Ref(None),
            &two,
            &llbc,
            false,
            false,
            &no_tombstones
        ),
        ValueType::Int
    );
    assert_eq!(
        super::input_param_value_type(
            ValueType::Ref(None),
            &two_f64,
            &llbc,
            false,
            false,
            &no_tombstones
        ),
        ValueType::Float
    );
    assert_eq!(
        super::input_param_value_type(
            ValueType::Ref(None),
            &two_char,
            &llbc,
            false,
            false,
            &no_tombstones
        ),
        ValueType::Int
    );
    assert_eq!(
        super::input_param_value_type(
            ValueType::Ref(None),
            &range,
            &llbc,
            false,
            false,
            &no_tombstones
        ),
        ValueType::Ref(None),
        "&Range stays a reference"
    );
    assert_eq!(
        super::tyref_scalar_pointee_value_type(&two, &llbc),
        None,
        "call-result banking still declines &&i64"
    );
}

#[test]
fn tyref_char_class_root_follows_nested_refs() {
    let llbc = fixture_llbc();
    let char_ty = serde_json::json!({"Scalar": "Char"});
    let by_value = TyRef::Other(char_ty.clone());
    let one = shared_of(char_ty.clone());
    let two = shared_of(serde_json::json!({"Ref": ["Erased", char_ty, "Shared"]}));
    let i64 = TyRef::Other(serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}}));
    assert_eq!(
        super::tyref_char_class_root(&by_value, &llbc).as_deref(),
        Some("char")
    );
    assert_eq!(
        super::tyref_char_class_root(&one, &llbc).as_deref(),
        Some("char")
    );
    assert_eq!(
        super::tyref_char_class_root(&two, &llbc).as_deref(),
        Some("char")
    );
    assert_eq!(super::tyref_char_class_root(&i64, &llbc), None);
}

/// A specialized copy's leaf matches its template's tail.
#[test]
fn a_spec_leaf_matches_its_template_tail() {
    use crate::front::mir::fmt_path_ends_with;
    let segs = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
    let spec = segs(&["lltype", "malloc_typed__spec_W_X_0123456789abcdef"]);
    assert!(fmt_path_ends_with(&spec, &["lltype", "malloc_typed"]));
    assert!(!fmt_path_ends_with(&spec, &["lltype", "malloc"]));
    let inner = segs(&["malloc_typed__spec_X_0123456789abcdef", "new"]);
    assert!(!fmt_path_ends_with(&inner, &["malloc_typed", "new"]));
    let identity = segs(&[
        "vec",
        "Vec",
        "<impl core::ops::index::Index<alloc::vec::Vec<v0,v2>,v1>>",
        "index",
    ]);
    assert!(fmt_path_ends_with(&identity, &["vec", "Vec", "index"]));
    let collect = segs(&[
        "iter",
        "traits",
        "collect",
        "<Impl>",
        "<impl core::iter::traits::collect::IntoIterator<core::ops::range::Range<v0>>>",
        "into_iter",
    ]);
    assert!(fmt_path_ends_with(
        &collect,
        &["iter", "traits", "collect", "<Impl>", "into_iter"]
    ));
}

#[test]
fn owner_method_path_accepts_trait_impl_identity() {
    use crate::front::mir::fmt_path_ends_with_owner_method;
    let segs = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
    let peq = &["core", "cmp", "PartialEq"][..];
    let owner = &["non_null", "NonNull"][..];
    let inherent = segs(&["ptr", "non_null", "NonNull", "eq"]);
    let identity = segs(&[
        "ptr",
        "non_null",
        "NonNull",
        "<impl core::cmp::PartialEq<core::ptr::non_null::NonNull<T>>>",
        "eq",
    ]);
    let charon_impl = segs(&["ptr", "non_null", "NonNull", "<Impl>", "ne"]);
    let foreign_eq = segs(&["ptr", "non_null", "NonNull", "<impl crate::MyEq>", "eq"]);
    let application_eq = segs(&[
        "ptr",
        "non_null",
        "NonNull",
        "<impl application::cmp::PartialEq<core::ptr::non_null::NonNull<T>>>",
        "eq",
    ]);
    let partial_ord = segs(&[
        "ptr",
        "non_null",
        "NonNull",
        "<impl core::cmp::PartialOrd<core::ptr::non_null::NonNull<T>>>",
        "eq",
    ]);
    let option_ext = segs(&["option", "Option", "<impl local::Ext>", "ne"]);
    assert!(fmt_path_ends_with_owner_method(&inherent, owner, peq, "eq"));
    assert!(fmt_path_ends_with_owner_method(&identity, owner, peq, "eq"));
    assert!(!fmt_path_ends_with_owner_method(
        &charon_impl,
        owner,
        peq,
        "ne"
    ));
    assert!(!fmt_path_ends_with_owner_method(
        &identity, owner, peq, "ne"
    ));
    assert!(!fmt_path_ends_with_owner_method(
        &segs(&["option", "Option", "eq"]),
        owner,
        peq,
        "eq"
    ));
    assert!(!fmt_path_ends_with_owner_method(
        &foreign_eq,
        owner,
        peq,
        "eq"
    ));
    assert!(!fmt_path_ends_with_owner_method(
        &application_eq,
        owner,
        peq,
        "eq"
    ));
    assert!(!fmt_path_ends_with_owner_method(
        &partial_ord,
        owner,
        peq,
        "eq"
    ));
    assert!(!fmt_path_ends_with_owner_method(
        &option_ext,
        &["option", "Option"],
        peq,
        "ne"
    ));
}

/// A Ref pointee is `{"Deduplicated": id}` of the Scalar
/// (`tyref_ref_pointee_value_type`), not `TyRef::Dedup`. The
/// primitive match must follow that wrapper so a `&[i64]` iterator
/// item is Signed and `retype_word` emits `intmask` (`intmask` /
/// `cast_uint_to_int`) after `ll_slice_getitem_fast_i`.
#[test]
fn nested_dedup_i64_pointee_classifies_as_signed() {
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [{
                "def_id": 0,
                "item_meta": {
                    "name": [{"Ident": ["fixture", 0]}, {"Ident": ["Seed", 0]}],
                    "span": {"data": {
                        "file_id": 0,
                        "beg": {"line": 1, "col": 0},
                        "end": {"line": 1, "col": 1}
                    }},
                    "source_text": null,
                    "attr_info": {
                        "attributes": [], "inline": null, "rename": null, "public": true
                    },
                    "is_local": true
                },
                "kind": {"Struct": [{
                    "name": null,
                    "ty": {"Value": [7, {"Scalar": {"Integer": {"Signed": "I64"}}}]},
                    "attr_info": null
                }]},
                "layout": null
            }],
            "fun_decls": [],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": []
        }
    });
    let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
    let pointee = TyRef::Other(serde_json::json!({"Deduplicated": 7}));
    assert_eq!(tyref_to_value_type(&pointee, &llbc), ValueType::Int);
    assert_eq!(tyref_to_attr_value_type(&pointee, &llbc), ValueType::Int);
    let borrowed = TyRef::Other(serde_json::json!({
        "Ref": ["Erased", {"Deduplicated": 7}, "Shared"]
    }));
    assert_eq!(
        tyref_to_value_type(&borrowed, &llbc),
        ValueType::Ref(None),
        "&i64 stays a reference; only its pointee is Signed"
    );
    let gc = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
    assert_eq!(
        super::tyref_ref_pointee_value_type(
            &borrowed,
            &llbc,
            super::no_tombstoned_leaves(),
            &gc,
            &std::collections::HashSet::<String>::new()
        ),
        Some(ValueType::Int)
    );
}

/// `&i64` and `i64` are different banks. `slice::Iter<i64>`'s type
/// argument is the scalar; the closure reads the borrow.
#[test]
fn map_collect_slice_iter_records_the_borrow_the_closure_reads() {
    let llbc = empty_llbc();
    let scalar = literal_i64();
    let borrow = shared_i64();
    assert_eq!(tyref_to_value_type(&scalar, &llbc), ValueType::Int);
    assert_eq!(
        tyref_to_value_type(&borrow, &llbc),
        ValueType::Ref(None),
        "&i64 and i64 must not share a bank"
    );
    assert!(super::iterator_adds_a_reference("core::slice::iter::Iter"));
    assert_eq!(
        super::map_collect_payload_value_type(&scalar, &llbc, true),
        ValueType::Ref(None),
        "Map::collect must record Iterator::Item &i64, not the type argument i64"
    );
}

/// `Enumerate<slice::Iter<i64>>::next` yields `(usize, &i64)`; the
/// `(index, item)` tuple of `enumerate(lst)` holds the list's item repr
/// (`EnumerateIteratorRepr.rtype_next` converts to `items_r[1]`), so the
/// reference the slice iterator added is peeled exactly as for a plain
/// `next`.
#[test]
fn enumerate_slice_iter_next_records_the_list_item() {
    let llbc = empty_llbc();
    let borrow = shared_i64();
    let node = match &borrow {
        TyRef::Other(v) => v.clone(),
        other => panic!("fixture ref must be inline, got {other:?}"),
    };
    assert_eq!(tyref_to_value_type(&borrow, &llbc), ValueType::Ref(None));
    let peeled = super::iterator_payload_element(&node, &llbc, true)
        .and_then(|item| serde_json::from_value::<TyRef>(item.clone()).ok())
        .map(|ty| tyref_to_value_type(&ty, &llbc));
    assert_eq!(peeled, Some(ValueType::Int));
}

fn branch_layout(disc_off: u64, payload_off: u64) -> majit_charon_reader::ullbc::TypeLayout {
    majit_charon_reader::ullbc::TypeLayout {
        size: Some(16),
        align: Some(8),
        variant_layouts: vec![
            majit_charon_reader::ullbc::VariantLayout {
                field_offsets: vec![payload_off],
                tagger: None,
            },
            majit_charon_reader::ullbc::VariantLayout {
                field_offsets: vec![payload_off],
                tagger: None,
            },
        ],
        discriminator: Some(serde_json::json!({
            "Branch": {"offset": disc_off, "int_ty": {"Signed": "I64"}}
        })),
        repr: None,
    }
}

fn graph_with_result_branch() -> (FunctionGraph, Variable) {
    let mut graph = FunctionGraph::new("result_branch");
    let entry = graph.startblock;
    let operand = graph
        .push_op_var(entry, OpKind::ConstInt(1), true)
        .expect("operand");
    let result = graph
        .push_op_var(
            entry,
            OpKind::Call {
                target: CallTarget::method("branch", Some("core::result::Result".into())),
                args: vec![LinkArg::Value(operand)],
                result_ty: ValueType::Ref(Some("core::ops::control_flow::ControlFlow".into())),
            },
            true,
        )
        .expect("branch");
    graph.set_return(entry, Some(result.clone()));
    (graph, result)
}

fn count_branch_calls(graph: &FunctionGraph) -> usize {
    graph
        .blocks
        .iter()
        .flat_map(|block| block.operations.iter())
        .filter(|op| {
            matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::Method { name, .. },
                    ..
                } if name == "branch"
            )
        })
        .count()
}

#[test]
fn equal_result_and_control_flow_layouts_lower_branch_to_same_as() {
    let same = branch_layout(0, 8);
    let (mut graph, _result) = graph_with_result_branch();
    let entry = graph.startblock;
    let call_idx = graph.block(entry).operations.iter().position(|op| {
        matches!(
            &op.kind,
            OpKind::Call {
                target: CallTarget::Method { name, .. },
                ..
            } if name == "branch"
        )
    });
    let call_idx = call_idx.expect("branch call");
    let kind = std::mem::replace(
        &mut graph.block_mut(entry).operations[call_idx].kind,
        OpKind::ConstInt(0),
    );
    graph.block_mut(entry).operations[call_idx].kind =
        super::rewrite_result_branch_for_layouts(kind, Some(&same), Some(&same));
    assert_eq!(count_branch_calls(&graph), 0);
    assert!(
        graph
            .blocks
            .iter()
            .flat_map(|block| block.operations.iter())
            .any(|op| { matches!(&op.kind, OpKind::UnaryOp { op, .. } if op == "same_as") }),
        "equal layouts keep the bits with same_as"
    );
}

#[test]
fn niche_result_layout_lowers_branch_as_a_discriminant_match() {
    let explicit = branch_layout(0, 8);
    let niche = branch_layout(8, 0);
    assert!(!super::type_layouts_equal(&explicit, &niche));
    let (mut graph, _result) = graph_with_result_branch();
    let entry = graph.startblock;
    let call_idx = graph
        .block(entry)
        .operations
        .iter()
        .position(|op| {
            matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::Method { name, .. },
                    ..
                } if name == "branch"
            )
        })
        .expect("branch call");
    let kind = graph.block(entry).operations[call_idx].kind.clone();
    let kept = super::rewrite_result_branch_for_layouts(kind, Some(&explicit), Some(&niche));
    assert!(
        matches!(
            kept,
            OpKind::Call {
                target: CallTarget::Method { name, .. },
                ..
            } if name == "branch"
        ),
        "unequal layouts stay a branch call"
    );
    super::lower_result_branch_to_control_flow(&mut graph);
    assert_eq!(count_branch_calls(&graph), 0, "branch must not stay a call");
    let reads_disc = graph
        .blocks
        .iter()
        .flat_map(|block| block.operations.iter())
        .any(|op| {
            matches!(
                &op.kind,
                OpKind::FieldRead { field, .. } if field.name == "__discriminant"
            )
        });
    assert!(reads_disc, "the match reads the Result discriminant");
    let mut ctors = Vec::new();
    for block in &graph.blocks {
        for op in &block.operations {
            if let OpKind::Call {
                target: CallTarget::SyntheticTransparentCtor { name, .. },
                ..
            } = &op.kind
            {
                ctors.push(name.clone());
            }
        }
    }
    assert!(ctors.iter().any(|name| name == "Continue"), "{ctors:?}");
    assert!(ctors.iter().any(|name| name == "Break"), "{ctors:?}");
}

fn result_flow_llbc() -> Llbc {
    let span = serde_json::json!({"data": {
        "file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}
    }});
    let meta = |path: &[&str]| {
        serde_json::json!({
            "name": path.iter().map(|seg| serde_json::json!({"Ident": [seg, 0]})).collect::<Vec<_>>(),
            "span": span.clone(),
            "source_text": null,
            "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
            "is_local": false
        })
    };
    let enum_decl = |def_id: u64, path: &[&str], variants: &[(&str, u64, u64)]| {
        serde_json::json!({
            "def_id": def_id,
            "item_meta": meta(path),
            "kind": {"Enum": variants.iter().map(|(name, disc, tvar)| serde_json::json!({
                "name": name,
                "fields": [{"name": null, "ty": {"TypeVar": {"Bound": [0, tvar]}}}],
                "discriminant": {"Scalar": {"Signed": ["Isize", disc.to_string()]}}
            })).collect::<Vec<_>>()},
            "layout": []
        })
    };
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [
                enum_decl(0, &["core", "result", "Result"], &[("Ok", 0, 0), ("Err", 1, 1)]),
                // `ControlFlow<B, C>`: Continue(C) is variant 0 (type var 1),
                // Break(B) is variant 1 (type var 0).
                enum_decl(1, &["core", "ops", "control_flow", "ControlFlow"], &[("Continue", 0, 1), ("Break", 1, 0)]),
            ],
            "fun_decls": [],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": []
        }
    });
    Llbc::from_slice(file.to_string().as_bytes()).expect("result/controlflow llbc")
}

fn branch_adt_ty(def_id: u64, args: &[serde_json::Value]) -> TyRef {
    serde_json::from_value(serde_json::json!({
        "Adt": {
            "id": def_id,
            "generics": {"regions": [], "types": args, "const_generics": [], "trait_refs": []}
        }
    }))
    .expect("adt ty")
}

fn branch_graph(payloads: crate::model::ResultBranchPayloads) -> FunctionGraph {
    let mut graph = FunctionGraph::new("result_branch_payload");
    let entry = graph.startblock;
    let operand = graph
        .push_op_var(entry, OpKind::ConstInt(1), true)
        .expect("operand");
    let result = graph
        .push_op_var(
            entry,
            OpKind::Call {
                target: CallTarget::method("branch", Some("core::result::Result".into()))
                    .with_branch_payloads(payloads),
                args: vec![LinkArg::Value(operand)],
                result_ty: ValueType::Ref(Some("core::ops::control_flow::ControlFlow".into())),
            },
            true,
        )
        .expect("branch");
    graph.set_return(entry, Some(result));
    graph
}

fn payload_field_tys(graph: &FunctionGraph) -> (Vec<ValueType>, Vec<ValueType>) {
    let mut reads = Vec::new();
    let mut writes = Vec::new();
    for op in graph
        .blocks
        .iter()
        .flat_map(|block| block.operations.iter())
    {
        match &op.kind {
            OpKind::FieldRead { field, ty, .. } if field.name == "__pos_0" => {
                reads.push(ty.clone());
            }
            OpKind::FieldWrite { field, ty, .. } if field.name == "__pos_0" => {
                writes.push(ty.clone());
            }
            _ => {}
        }
    }
    (reads, writes)
}

#[test]
fn result_branch_match_uses_int_payloads_from_the_type_decls() {
    let i64_ty = serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}});
    let u8_ty = serde_json::json!({"Scalar": {"Integer": {"Unsigned": "U8"}}});
    let llbc = result_flow_llbc();
    let result_ty = branch_adt_ty(0, &[i64_ty.clone(), u8_ty.clone()]);
    // ControlFlow<B, C = U8, I64>: Break is B, Continue is C.
    let flow_ty = branch_adt_ty(1, &[u8_ty, i64_ty]);
    let tombstoned = std::collections::HashSet::new();
    let payloads = crate::model::ResultBranchPayloads {
        ok: super::adt_variant_payload_type(
            &result_ty,
            "Ok",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        err: super::adt_variant_payload_type(
            &result_ty,
            "Err",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        continue_ty: super::adt_variant_payload_type(
            &flow_ty,
            "Continue",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        break_ty: super::adt_variant_payload_type(
            &flow_ty,
            "Break",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
    };
    assert_eq!(payloads.ok, Some(ValueType::Int));
    assert_eq!(payloads.err, Some(ValueType::Unsigned));
    assert_eq!(payloads.continue_ty, Some(ValueType::Int));
    assert_eq!(payloads.break_ty, Some(ValueType::Unsigned));
    let mut graph = branch_graph(payloads);
    super::lower_result_branch_to_control_flow(&mut graph);
    let (reads, writes) = payload_field_tys(&graph);
    assert_eq!(reads, vec![ValueType::Int, ValueType::Unsigned]);
    assert_eq!(writes, vec![ValueType::Int, ValueType::Unsigned]);
}

#[test]
fn result_branch_break_of_infallible_result_builds_err() {
    let i64_ty = serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}});
    let llbc = result_flow_llbc();
    let infallible = serde_json::json!({
        "Adt": {"id": 99, "generics": {"regions": [], "types": [], "const_generics": [], "trait_refs": []}}
    });
    let residual = serde_json::json!({
        "Adt": {
            "id": 0,
            "generics": {"regions": [], "types": [infallible, i64_ty.clone()], "const_generics": [], "trait_refs": []}
        }
    });
    let result_ty = branch_adt_ty(0, &[i64_ty.clone(), i64_ty.clone()]);
    // ControlFlow<Result<Infallible, i64>, i64>: type 0 is Break, type 1 is Continue.
    let flow_ty = branch_adt_ty(1, &[residual, i64_ty]);
    let tombstoned = std::collections::HashSet::new();
    let payloads = crate::model::ResultBranchPayloads {
        ok: super::adt_variant_payload_type(
            &result_ty,
            "Ok",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        err: super::adt_variant_payload_type(
            &result_ty,
            "Err",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        continue_ty: super::adt_variant_payload_type(
            &flow_ty,
            "Continue",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        break_ty: super::adt_variant_payload_type(
            &flow_ty,
            "Break",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
    };
    assert_eq!(payloads.ok, Some(ValueType::Int));
    assert_eq!(payloads.err, Some(ValueType::Int));
    assert_eq!(payloads.continue_ty, Some(ValueType::Int));
    assert_ne!(
        payloads.break_ty, payloads.err,
        "Result<Infallible, i64> is not banked as i64"
    );
    let mut graph = branch_graph(payloads);
    super::lower_result_branch_to_control_flow(&mut graph);
    let mut ctors = Vec::new();
    for block in &graph.blocks {
        for op in &block.operations {
            if let OpKind::Call {
                target: CallTarget::SyntheticTransparentCtor { name, .. },
                ..
            } = &op.kind
            {
                ctors.push(name.clone());
            }
        }
    }
    assert!(
        ctors.iter().any(|name| name == "Err"),
        "Break payload must be Result::Err, got {ctors:?}"
    );
    let (reads, writes) = payload_field_tys(&graph);
    assert_eq!(reads, vec![ValueType::Int, ValueType::Int]);
    assert!(
        writes.iter().any(|ty| matches!(
            ty,
            ValueType::Ref(Some(name)) if name.starts_with("Result<")
        )),
        "Break stores the Result value, got {writes:?}"
    );
}

#[test]
fn result_branch_match_emits_nothing_for_void_payloads() {
    let unit = serde_json::json!({"Adt": {"id": 0, "builtin": "Tuple", "generics": {"types": []}}});
    let llbc = result_flow_llbc();
    let result_ty = branch_adt_ty(0, &[unit.clone(), unit.clone()]);
    let flow_ty = branch_adt_ty(1, &[unit.clone(), unit]);
    let tombstoned = std::collections::HashSet::new();
    let payloads = crate::model::ResultBranchPayloads {
        ok: super::adt_variant_payload_type(
            &result_ty,
            "Ok",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        err: super::adt_variant_payload_type(
            &result_ty,
            "Err",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        continue_ty: super::adt_variant_payload_type(
            &flow_ty,
            "Continue",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
        break_ty: super::adt_variant_payload_type(
            &flow_ty,
            "Break",
            &llbc,
            &tombstoned,
            &super::harvest_declared_gc_facts(&llbc).gc_struct_ids(),
            &std::collections::HashSet::<String>::new(),
        ),
    };
    assert_eq!(payloads.ok, None);
    assert_eq!(payloads.err, None);
    assert_eq!(payloads.continue_ty, None);
    assert_eq!(payloads.break_ty, None);
    let mut graph = branch_graph(payloads);
    super::lower_result_branch_to_control_flow(&mut graph);
    let (reads, writes) = payload_field_tys(&graph);
    assert!(reads.is_empty(), "void payload emits no read: {reads:?}");
    assert!(writes.is_empty(), "void payload emits no field: {writes:?}");
    assert_eq!(count_branch_calls(&graph), 0);
}

#[test]
fn map_err_capture_requires_the_core_result_callee() {
    for path in [
        "core::result::<Impl>::map_err",
        "std::result::<Impl>::map_err",
        "core::result::Result::map_err",
        "std::result::Result::map_err",
    ] {
        assert!(is_core_result_map_err_path(path), "{path}");
        assert!(super::is_core_result_method(path, "map_err"), "{path}");
    }
    for path in ["result::Result::map_err", "result::<Impl>::map_err"] {
        assert!(is_core_result_map_err_path(path), "{path}");
    }
    for path in [
        "map_err",
        "Result::map_err",
        "mycrate::result::<Impl>::map_err",
        "core::result::ResultExt::<Impl>::map_err",
        "foo::bar::map_err",
    ] {
        assert!(!is_core_result_map_err_path(path), "{path}");
    }
}

