/// A block emptied *after* the head `eliminate_empty_blocks` must still
/// be rewired past, so the values riding the link into it do not survive
/// lowering as dead link args.
///
/// Shape reproduced from `pyre_interpreter::pyframe::<Impl>::set_locals_w`:
/// the forwarding block holds one dead unit-`()` constructor, so it is
/// *not* empty when the head call runs; `prune_dead_boxing_remnants` /
/// `remove_dead_aggregates` drop that constructor, and the block is empty
/// only from then on.  The array the entry block writes to rides the link
/// into it, and `prune_dead_phis` cannot reclaim that link arg because the
/// forwarding block reuses the predecessor's `Variable` identities, so
/// per-variable liveness sees the array as read — by the predecessor's own
/// `ArrayWrite`.
#[test]
fn block_emptied_after_the_head_collapse_is_still_rewired_past() {
    let unit_ctor = || OpKind::Call {
        target: CallTarget::synthetic_transparent_ctor("Tuple"),
        args: Vec::new(),
        result_ty: ValueType::Ref(Some("Tuple".to_string())),
    };

    let mut graph = FunctionGraph::new("test");
    let entry = graph.startblock;
    let array = graph
        .push_op_var(entry, OpKind::ConstInt(1), true)
        .expect("array var");
    let index = graph
        .push_op_var(entry, OpKind::ConstInt(0), true)
        .expect("index var");
    let value = graph
        .push_op_var(entry, OpKind::ConstInt(7), true)
        .expect("value var");
    // Side-effecting, so `prune_dead_phis` pins `array` in `read_vars`.
    graph.push_op_var(
        entry,
        OpKind::ArrayWrite {
            base: array.clone(),
            index,
            value: LinkArg::Value(value),
            item_ty: ValueType::Int,
            array_type_id: None,
            nolength: false,
        },
        false,
    );
    // The dead unit-`()` value the entry block also builds.
    graph.push_op_var(entry, unit_ctor(), true);

    let forwarding = graph.create_block();
    // The forwarding block reuses the predecessor's `Variable`, which is
    // what defeats positional liveness in the real graph.
    graph.block_mut(forwarding).inputargs = vec![array.clone()];
    graph.push_op_var(forwarding, unit_ctor(), true);
    graph.set_goto(entry, forwarding, vec![array.clone()]);
    graph.set_return(forwarding, None);

    simplify_lowered_graph(
        &mut graph,
        &std::collections::HashMap::new(),
        true,
        &std::collections::HashSet::new(),
    );

    let entry_exit = &graph.block(entry).exits[0];
    assert_eq!(
        entry_exit.target, graph.returnblock,
        "the emptied forwarding block must be rewired past"
    );
    assert!(
        !entry_exit
            .args
            .iter()
            .any(|arg| arg.as_variable() == Some(&array)),
        "the array must not survive as a dead link arg: {:?}",
        entry_exit.args
    );
    assert!(
        graph.block(forwarding).inputargs.is_empty(),
        "the orphaned block must be cleared, not left naming the array: {:?}",
        graph.block(forwarding).inputargs
    );
}

fn struct_ctor_graph(pass_to_malloc: bool) -> FunctionGraph {
    struct_ctor_graph_escaping(pass_to_malloc, StructCtorEscape::UniqueLocal)
}

#[derive(Clone, Copy)]
enum StructCtorEscape {
    /// Field reads only; the aggregate itself does not escape.
    UniqueLocal,
    /// `return s` — a by-value move to the caller.
    Returned,
    /// Passed to a residual call that expects the by-value layout.
    CallArg,
    /// Copied into a successor phi, then mutated.
    Phi,
}

fn struct_ctor_graph_escaping(pass_to_malloc: bool, escape: StructCtorEscape) -> FunctionGraph {
    let mut graph = FunctionGraph::new("struct_ctor");
    let entry = graph.startblock;
    let owner = "error::DictKeyError";
    let result = graph
        .push_op_var(
            entry,
            OpKind::Call {
                target: CallTarget::synthetic_transparent_struct_ctor(
                    vec!["error".to_string()],
                    "DictKeyError",
                ),
                args: Vec::new(),
                result_ty: ValueType::Ref(Some(owner.to_string())),
            },
            true,
        )
        .expect("struct ctor");
    let payload = graph
        .push_op_var(entry, OpKind::ConstInt(1), true)
        .expect("payload");
    graph.push_op_var(
        entry,
        OpKind::FieldWrite {
            base: result.clone(),
            field: FieldDescriptor::new("kind", Some(owner.to_string())),
            value: LinkArg::Value(payload.clone()),
            ty: ValueType::Int,
        },
        false,
    );
    if pass_to_malloc {
        graph.push_op_var(
            entry,
            OpKind::Call {
                target: CallTarget::function_path(["runtime_object", "lltype", "malloc_typed"]),
                args: crate::model::call_args(vec![result.clone()]),
                result_ty: ValueType::Ref(Some(owner.to_string())),
            },
            true,
        );
    }
    match escape {
        StructCtorEscape::UniqueLocal => {
            let kind = graph
                .push_op_var(
                    entry,
                    OpKind::FieldRead {
                        base: result,
                        field: FieldDescriptor::new("kind", Some(owner.to_string())),
                        ty: ValueType::Int,
                        pure: true,
                    },
                    true,
                )
                .expect("field read");
            graph.set_return(entry, Some(kind));
        }
        StructCtorEscape::Returned => graph.set_return(entry, Some(result)),
        StructCtorEscape::CallArg => {
            graph.push_op_var(
                entry,
                OpKind::Call {
                    target: CallTarget::function_path(["slice", "index"]),
                    args: crate::model::call_args(vec![result]),
                    result_ty: ValueType::Int,
                },
                true,
            );
            graph.set_return(entry, None);
        }
        StructCtorEscape::Phi => {
            let (next, args) = graph.create_block_with_arg_vars(1);
            let copy = args[0].clone();
            graph.push_op_var(
                next,
                OpKind::FieldWrite {
                    base: copy,
                    field: FieldDescriptor::new("kind", Some(owner.to_string())),
                    value: LinkArg::Value(payload),
                    ty: ValueType::Int,
                },
                false,
            );
            graph.set_goto(entry, next, vec![result]);
            graph.set_return(next, None);
        }
    }
    graph
}

fn struct_ctor_ops(graph: &FunctionGraph) -> (usize, usize, usize) {
    let mut ctors = 0usize;
    let mut news = 0usize;
    let mut field_writes = 0usize;
    for op in graph.blocks.iter().flat_map(|block| &block.operations) {
        match &op.kind {
            OpKind::Call {
                target:
                    CallTarget::SyntheticTransparentCtor {
                        is_struct: true, ..
                    },
                ..
            } => ctors += 1,
            OpKind::New { owner } if owner == "error::DictKeyError" => news += 1,
            OpKind::FieldWrite { field, .. } if field.name == "kind" => field_writes += 1,
            _ => {}
        }
    }
    (ctors, news, field_writes)
}

fn empty_struct_attrs() -> std::collections::HashMap<String, Vec<(String, ValueType)>> {
    std::collections::HashMap::new()
}

fn replace_struct_ctors(graph: &mut FunctionGraph) -> usize {
    scalar_replace_named_struct_aggregates(graph, &empty_struct_attrs())
}

fn same_as_count(graph: &FunctionGraph) -> usize {
    graph
        .blocks
        .iter()
        .flat_map(|block| &block.operations)
        .filter(|op| matches!(&op.kind, OpKind::UnaryOp { op, .. } if op == "same_as"))
        .count()
}

fn struct_news(graph: &FunctionGraph) -> Vec<Variable> {
    graph
        .blocks
        .iter()
        .flat_map(|block| &block.operations)
        .filter_map(|op| match &op.kind {
            OpKind::New { owner } if owner == "error::DictKeyError" => op.result.clone(),
            _ => None,
        })
        .collect()
}

