/// Anchor the `&self` `Option::is_some` fold to the real lowered IR of
/// `callable_w` — `lookup_in_type(t, "__call__").is_some()`.  The
/// receiver is an owned `Option<PyObjectRef>` that Rust auto-refs to
/// `&Option` at the call, so the receiver type arrives as `Ref(Option)`;
/// the `_ref` guard + `tyref_ref_adt_def_id` peel it (the by-value
/// `tyref_is_option` would see the `Ref` and miss).  After the fold no
/// residual `is_some` Method call survives and a `__discriminant` read is
/// present.  Ignored by default (loads the real LLBC).
#[test]
#[ignore]
fn is_some_fold_real_callable_w() {
    use crate::model::{CallTarget, OpKind};

    let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
    let llbc = Llbc::load(path).expect("load real LLBC");
    let graph = super::lower_function(&llbc, "callable_w").expect("lower callable_w");

    let method_calls = |leaf: &str| {
        graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call { target: CallTarget::Method { name, .. }, .. }
                        if name == leaf
                )
            })
            .count()
    };
    assert_eq!(
        method_calls("is_some"),
        0,
        "residual &Option::is_some Method call removed by the fold"
    );
    let disc_reads = graph
            .blocks
            .iter()
            .flat_map(|b| b.operations.iter())
            .filter(|op| {
                matches!(&op.kind, OpKind::FieldRead { field, .. } if field.name == "__discriminant")
            })
            .count();
    assert!(disc_reads >= 1, "the fold reads the Option __discriminant");
}

/// Anchor the `Option::or_else` fold to the real lowered IR of
/// `space_int` — `lookup(obj, "__int__").or_else(|| lookup(obj,
/// "__index__"))`.  `or_else` takes `self` by value (like the sibling
/// closure-select combinators), so the by-value receiver resolution
/// applies.  After the fold no residual `or_else` Method call survives,
/// the discriminant diamond branches, and the `Some` arm forwards the
/// receiver (no `Some::__pos_0` read introduced by the rewrite).  Ignored
/// by default (loads the real LLBC).
#[test]
#[ignore]
fn or_else_fold_real_space_int() {
    use crate::model::{CallTarget, OpKind};

    let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
    let llbc = Llbc::load(path).expect("load real LLBC");
    let graph = super::lower_function(&llbc, "space_int").expect("lower space_int");

    let or_else_calls = graph
        .blocks
        .iter()
        .flat_map(|b| b.operations.iter())
        .filter(|op| {
            matches!(
                &op.kind,
                OpKind::Call { target: CallTarget::Method { name, .. }, .. }
                    if name == "or_else"
            )
        })
        .count();
    assert_eq!(
        or_else_calls, 0,
        "residual or_else Method call removed by the fold"
    );
    // The niladic `None`-arm closure lowers to a `call_once` Method call.
    let call_once = graph
        .blocks
        .iter()
        .flat_map(|b| b.operations.iter())
        .filter(|op| {
            matches!(
                &op.kind,
                OpKind::Call { target: CallTarget::Method { name, .. }, .. }
                    if name == "call_once"
            )
        })
        .count();
    assert!(
        call_once >= 1,
        "the None arm calls the or_else closure via call_once"
    );
}

/// The field-bearing primary driver const must lower exactly like the
/// zero-field unpack driver: one opaque constant receiver for each marker,
/// never a residual call to the const item's symbolic path.  Ignored by
/// default because it loads the extracted pyre-jit artefact; run with
/// `cargo test -p majit-translate --lib
/// pypyjitdriver_named_const_is_a_marker_receiver_constant -- --ignored`.
#[test]
#[ignore]
fn pypyjitdriver_named_const_is_a_marker_receiver_constant() {
    use crate::model::{CallTarget, OpKind};

    let llbc = Llbc::load(crate::runtime_names::artifacts::JIT_ULLBC).expect("load pyre-jit LLBC");
    let graph = super::lower_function(&llbc, "eval_loop_jit").expect("lower eval_loop_jit");
    let driver_path = ["pyre_jit", "eval", "pypyjitdriver"];

    assert!(
        !graph
            .blocks
            .iter()
            .flat_map(|block| &block.operations)
            .any(|op| matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    args,
                    ..
                } if args.is_empty()
                    && super::fmt_path_ends_with(segments, &driver_path)
            )),
        "the driver const path must not survive as a nullary call"
    );

    let marker_receivers: Vec<_> = graph
        .blocks
        .iter()
        .flat_map(|block| &block.operations)
        .filter_map(|op| match &op.kind {
            OpKind::Call {
                target:
                    CallTarget::Method {
                        name,
                        receiver_root: Some(root),
                        ..
                    },
                args,
                ..
            } if root == "PyPyJitDriver"
                && matches!(name.as_str(), "jit_merge_point" | "can_enter_jit") =>
            {
                args.first()
            }
            _ => None,
        })
        .collect();
    assert_eq!(
        marker_receivers.len(),
        2,
        "eval_loop_jit must retain both source marker calls after MIR lowering"
    );
    for receiver in marker_receivers {
        let (block_id, op_index) = super::resolve_to_producer_op(&graph, receiver)
            .expect("marker receiver has one producer");
        let producer = &graph
            .blocks
            .iter()
            .find(|block| block.id == block_id)
            .expect("producer block")
            .operations[op_index];
        assert!(
            matches!(
                producer.kind,
                OpKind::ConstRefAddr(super::JITDRIVER_NAMEDCONST_SENTINEL_ADDR)
            ),
            "marker receiver producer must be the driver sentinel: {producer:?}"
        );
    }
}

/// rustc's promoted-const wrapper copies one `Place::Global` and
/// returns a reference. That inner id is the NamedConst `getfunctionptr`
/// would name (`Transformer.handle_residual_call`).
#[test]
fn promoted_const_initializer_copies_the_inner_global() {
    let body: majit_charon_reader::ullbc::Unstructured = serde_json::from_value(serde_json::json!({
            "span": {"Deduplicated": 0},
            "locals": {"arg_count": 0, "locals": []},
            "body": [{
                "statements": [
                    {"span": {"Deduplicated": 0}, "kind": {"StorageLive": 1}},
                    {"span": {"Deduplicated": 0}, "kind": {"Assign": [
                        {"kind": {"Local": 1}, "ty": {"Deduplicated": 0}},
                        {"Use": [{"Copy": {
                            "kind": {"Global": {
                                "id": 31,
                                "generics": {"regions": [], "types": [], "const_generics": [], "trait_refs": []}
                            }},
                            "ty": {"Deduplicated": 0}
                        }}, "Yes"]}
                    ]}},
                    {"span": {"Deduplicated": 0}, "kind": {"Assign": [
                        {"kind": {"Local": 0}, "ty": {"Deduplicated": 0}},
                        {"Ref": {
                            "place": {"kind": {"Local": 1}, "ty": {"Deduplicated": 0}},
                            "kind": "Shared",
                            "ptr_metadata": {"Const": {"Deduplicated": 0}}
                        }}
                    ]}}
                ],
                "terminator": {"span": {"Deduplicated": 0}, "kind": "Return"},
                "kind": "Regular"
            }]
        }))
        .expect("promoted-const wrapper fixture parses");
    let place = super::promoted_const_copied_global(&body).expect("inner global");
    assert_eq!(super::inner_global_id(&place), 31);
}

/// rustc promotes a `&str` literal to `_1 = const C; _0 = &_1`.
#[test]
fn promoted_const_initializer_copies_the_inner_const() {
    let body: majit_charon_reader::ullbc::Unstructured =
        serde_json::from_value(serde_json::json!({
            "span": {"Deduplicated": 0},
            "locals": {"arg_count": 0, "locals": []},
            "body": [{
                "statements": [
                    {"span": {"Deduplicated": 0}, "kind": {"StorageLive": 1}},
                    {"span": {"Deduplicated": 0}, "kind": {"Assign": [
                        {"kind": {"Local": 1}, "ty": {"Deduplicated": 0}},
                        {"Use": [{"Const": {"Deduplicated": 20437}}, "Yes"]}
                    ]}},
                    {"span": {"Deduplicated": 0}, "kind": {"Assign": [
                        {"kind": {"Local": 0}, "ty": {"Deduplicated": 0}},
                        {"Ref": {
                            "place": {"kind": {"Local": 1}, "ty": {"Deduplicated": 0}},
                            "kind": "Shared",
                            "ptr_metadata": {"Const": {"Deduplicated": 0}}
                        }}
                    ]}}
                ],
                "terminator": {"span": {"Deduplicated": 0}, "kind": "Return"},
                "kind": "Regular"
            }]
        }))
        .expect("promoted-const literal wrapper fixture parses");
    let value = super::promoted_const_copied_const(&body).expect("inner const");
    assert_eq!(
        value.get("Deduplicated").and_then(|v| v.as_u64()),
        Some(20437)
    );
}

fn promoted_const_unstructured(
    blocks: serde_json::Value,
) -> majit_charon_reader::ullbc::Unstructured {
    serde_json::from_value(serde_json::json!({
        "span": {"Deduplicated": 0},
        "locals": {"arg_count": 0, "locals": []},
        "body": blocks
    }))
    .expect("promoted-const fixture parses")
}

fn global_place(id: u64) -> serde_json::Value {
    serde_json::json!({
        "kind": {"Global": {
            "id": id,
            "generics": {"regions": [], "types": [], "const_generics": [], "trait_refs": []}
        }},
        "ty": {"Deduplicated": 0}
    })
}

fn local_place(id: u64) -> serde_json::Value {
    serde_json::json!({"kind": {"Local": id}, "ty": {"Deduplicated": 0}})
}

fn assign_copy(dest: serde_json::Value, src: serde_json::Value) -> serde_json::Value {
    serde_json::json!({
        "span": {"Deduplicated": 0},
        "kind": {"Assign": [dest, {"Use": [{"Copy": src}, "Yes"]}]}
    })
}

fn assign_shared_ref(dest: serde_json::Value, src: serde_json::Value) -> serde_json::Value {
    serde_json::json!({
        "span": {"Deduplicated": 0},
        "kind": {"Assign": [dest, {"Ref": {
            "place": src,
            "kind": "Shared",
            "ptr_metadata": {"Const": {"Deduplicated": 0}}
        }}]}
    })
}

fn return_bb(statements: Vec<serde_json::Value>) -> serde_json::Value {
    serde_json::json!({
        "statements": statements,
        "terminator": {"span": {"Deduplicated": 0}, "kind": "Return"},
        "kind": "Regular"
    })
}

/// Shape (b): `_0 = copy Global(id); return`.
#[test]
fn promoted_const_initializer_copies_the_inner_global_by_value() {
    let body = promoted_const_unstructured(serde_json::json!([return_bb(vec![assign_copy(
        local_place(0),
        global_place(31)
    ),])]));
    let place = super::promoted_const_copied_global(&body).expect("inner global");
    assert_eq!(super::inner_global_id(&place), 31);
}

/// `_1 = copy G; _0 = &(_1.field); return` is not a read of G.
#[test]
fn promoted_const_initializer_rejects_field_projection_ref() {
    let field = serde_json::json!({
        "kind": {"Projection": [local_place(1), {"Field": [null, 0]}]},
        "ty": {"Deduplicated": 0}
    });
    let body = promoted_const_unstructured(serde_json::json!([return_bb(vec![
        assign_copy(local_place(1), global_place(31)),
        assign_shared_ref(local_place(0), field),
    ])]));
    assert!(super::promoted_const_copied_global(&body).is_none());
}

/// rustc's promoted-const wrapper does not emit a local-to-local copy
/// chain (`_2 = copy _1; _0 = &_2`). Reject it so a copy of a copy is
/// not folded as the global.
#[test]
fn promoted_const_initializer_rejects_local_to_local_copy_chain() {
    let body = promoted_const_unstructured(serde_json::json!([return_bb(vec![
        assign_copy(local_place(1), global_place(31)),
        assign_copy(local_place(2), local_place(1)),
        assign_shared_ref(local_place(0), local_place(2)),
    ])]));
    assert!(super::promoted_const_copied_global(&body).is_none());
}

/// A global copied only in an unreachable block is not the returned value.
#[test]
fn promoted_const_initializer_rejects_unreachable_block_global() {
    let unreachable = return_bb(vec![
        assign_copy(local_place(1), global_place(31)),
        assign_shared_ref(local_place(0), local_place(1)),
    ]);
    let entry = serde_json::json!({
        "statements": [],
        "terminator": {"span": {"Deduplicated": 0}, "kind": "Return"},
        "kind": "Regular"
    });
    let body = promoted_const_unstructured(serde_json::json!([entry, unreachable]));
    assert!(super::promoted_const_copied_global(&body).is_none());
    assert!(super::promoted_const_copied_const(&body).is_none());
}

/// `resolve_place` of a projected global falls back to the inner Global
/// and drops the field, so a copy of `G.field` is not accepted as G.
#[test]
fn promoted_const_initializer_rejects_projected_global() {
    let projected = serde_json::json!({
        "kind": {"Projection": [global_place(31), {"Field": [null, 0]}]},
        "ty": {"Deduplicated": 0}
    });
    let body = promoted_const_unstructured(serde_json::json!([return_bb(vec![
        assign_copy(local_place(1), projected),
        assign_shared_ref(local_place(0), local_place(1)),
    ])]));
    assert!(super::promoted_const_copied_global(&body).is_none());
}

