/// The real `RangeBounds::contains` body is the caller of the two
/// comparisons (`start <= x && x < end` via `le`/`lt`). `int_between` is
/// not emitted: RPython only has that llop because source calls
/// `rarithmetic.int_between` (`rint.py`). Ignored by default (loads
/// the real LLBC); run with `cargo test -p majit-translate --lib
/// range_contains_real_body -- --ignored --nocapture`.
#[test]
#[ignore]
fn range_contains_real_body_carries_le_lt() {
    use crate::model::{CallTarget, OpKind};

    let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
    let llbc = Llbc::load(path).expect("load real LLBC");
    let ctx = super::LowerContext::new(&llbc);

    let mut bounds_contains = None;
    let mut range_contains = None;
    for fd in llbc.iter_fun_decls() {
        if !fd.has_unstructured_body() {
            continue;
        }
        let p = fd.item_meta.name_path();
        if !p.ends_with("::contains") || !p.contains("ops::range") {
            continue;
        }
        if p.contains("RangeBounds") {
            bounds_contains = Some(fd);
        } else if p.contains("RangeInclusive") {
            continue;
        } else if p.contains("Range") {
            range_contains = Some(fd);
        }
    }
    let bounds_fd = bounds_contains.expect("RangeBounds::contains FunDecl with a body");
    let bounds_graph = super::lower_fun_decl(&ctx, bounds_fd)
        .unwrap_or_else(|e| panic!("lower RangeBounds::contains: {e:?}"));

    let mut leaves: Vec<String> = Vec::new();
    let mut binops: Vec<String> = Vec::new();
    let mut int_between = 0usize;
    for op in bounds_graph.blocks.iter().flat_map(|b| b.operations.iter()) {
        match &op.kind {
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                ..
            } => {
                if let Some(leaf) = segments.last() {
                    leaves.push(leaf.clone());
                }
            }
            OpKind::Call {
                target: CallTarget::Method { name, .. },
                ..
            } => leaves.push(name.clone()),
            OpKind::BinOp { op, .. } => binops.push(op.clone()),
            OpKind::LoweredBlackholeOp { opname, .. } if opname == "int_between" => {
                int_between += 1;
            }
            _ => {}
        }
    }
    eprintln!(
        "RangeBounds::contains path={} leaves={leaves:?} binops={binops:?} int_between={int_between}",
        bounds_fd.item_meta.name_path()
    );
    assert_eq!(int_between, 0, "body must not emit int_between");
    let has = |name: &str| leaves.iter().any(|l| l == name) || binops.iter().any(|b| b == name);
    assert!(has("start_bound"), "missing start_bound: {leaves:?}");
    assert!(has("end_bound"), "missing end_bound: {leaves:?}");
    assert!(has("le"), "missing le: leaves={leaves:?} binops={binops:?}");
    assert!(has("lt"), "missing lt: leaves={leaves:?} binops={binops:?}");

    if let Some(range_fd) = range_contains {
        let range_graph = super::lower_fun_decl(&ctx, range_fd)
            .unwrap_or_else(|e| panic!("lower Range::contains: {e:?}"));
        let mut range_leaves: Vec<String> = Vec::new();
        let mut range_between = 0usize;
        for op in range_graph.blocks.iter().flat_map(|b| b.operations.iter()) {
            match &op.kind {
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } => {
                    if let Some(leaf) = segments.last() {
                        range_leaves.push(leaf.clone());
                    }
                }
                OpKind::Call {
                    target: CallTarget::Method { name, .. },
                    ..
                } => range_leaves.push(name.clone()),
                OpKind::LoweredBlackholeOp { opname, .. } if opname == "int_between" => {
                    range_between += 1;
                }
                _ => {}
            }
        }
        eprintln!(
            "Range::contains path={} leaves={range_leaves:?} int_between={range_between}",
            range_fd.item_meta.name_path()
        );
        assert_eq!(range_between, 0);
    }
}

/// `formatting::char_arg` narrows its BigInt to `u32`, not `i64`.  The
/// i64-specific fits/discriminant synthesis must decline and leave the
/// original `TryFrom<&BigInt>` call residual.  Ignored by default because
/// it loads the real interpreter LLBC.
#[test]
#[ignore]
fn bigint_i64_try_from_real_declines_u32_result() {
    use crate::model::{CallTarget, OpKind};

    let path = crate::runtime_names::artifacts::INTERPRETER_ULLBC;
    let llbc = Llbc::load(path).expect("load real LLBC");
    let graph = super::lower_function(&llbc, "char_arg").expect("lower char_arg");

    let calls: Vec<&[String]> = graph
        .blocks
        .iter()
        .flat_map(|b| b.operations.iter())
        .filter_map(|op| match &op.kind {
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                ..
            } => Some(segments.as_slice()),
            _ => None,
        })
        .collect();
    assert!(
        calls.iter().any(|segments| {
            super::fmt_path_ends_with(segments, &["bigint", "<Impl>", "try_from"])
                || super::fmt_path_ends_with(segments, &["<Impl>", "try_from"])
        }),
        "u32::try_from(&BigInt) must remain a residual FunctionPath call"
    );
    assert!(
        !calls.iter().any(|segments| {
            segments.last().map(String::as_str) == Some("jit_bigint_to_i64_fits")
        }),
        "u32 destination must not use the i64 fits/discriminant lowering"
    );
}

/// PyPy's `ObjSpace.c_int_w` performs the same signed 32-bit bounds
/// check explicitly. Anchor Rust's `i32::try_from(i64)` spelling in both
/// the interpreter helper and the int-or-float list strategy: neither may
/// retain an opaque core call, and both must keep a runtime Result tag.
#[test]
#[ignore]
fn i64_to_i32_try_from_real_sites_lower_to_checked_result() {
    use crate::model::{CallTarget, OpKind};

    for (relpath, fname) in [
        ("/../../target/llbc/pyre-interpreter.ullbc", "index_c_int_w"),
        (
            "/../../target/llbc/pyre-object.ullbc",
            "int_or_float_encode_int",
        ),
    ] {
        let path = format!("{}{relpath}", env!("CARGO_MANIFEST_DIR"));
        let llbc = Llbc::load(path).unwrap_or_else(|e| panic!("load {fname} LLBC: {e}"));
        let graph =
            super::lower_function(&llbc, fname).unwrap_or_else(|e| panic!("lower {fname}: {e:?}"));
        assert!(
                !graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
                    matches!(&op.kind, OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if super::fmt_path_ends_with(
                            segments,
                            &["convert", "num", "<Impl>", "try_from"],
                        ))
                }),
                "{fname}: checked narrowing must not remain an opaque core call"
            );
        // `or`, not a sum: `c_int_w` writes
        // `value < INT_MIN or value > INT_MAX` (`baseobjspace.py`).
        for expected in ["lt", "gt", "or"] {
            assert!(
                graph
                    .blocks
                    .iter()
                    .flat_map(|b| &b.operations)
                    .any(|op| { matches!(&op.kind, OpKind::BinOp { op, .. } if op == expected) }),
                "{fname}: missing checked-narrowing {expected} op"
            );
        }
        assert!(
            graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
                matches!(&op.kind, OpKind::FieldWrite { field, .. }
                        if field.name == "__discriminant")
            }),
            "{fname}: Result discriminant must remain runtime data"
        );
    }
}

/// `w_range_iter` keeps the word iterator only when
/// `start + length * step` still fits i64 (`i64::try_from(i128)`).
/// That shell is the same checked Result `c_int_w` writes, with
/// `longlongmask` on the Ok payload (`rbuiltin.py`).
#[test]
fn w_range_iter_i128_try_from_lowers_to_checked_result() {
    use crate::model::{CallTarget, OpKind};

    let path = format!(
        "{}/../../target/llbc/pyre-object.ullbc",
        env!("CARGO_MANIFEST_DIR")
    );
    let llbc = Llbc::load(path).unwrap_or_else(|e| panic!("load w_range_iter LLBC: {e}"));
    let graph = super::lower_function(&llbc, "w_range_iter")
        .unwrap_or_else(|e| panic!("lower w_range_iter: {e:?}"));
    assert!(
            !graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
                matches!(&op.kind, OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                    if super::fmt_path_ends_with(
                        segments,
                        &["convert", "num", "<Impl>", "try_from"],
                    ))
            }),
            "w_range_iter: i128 try_from must not remain an opaque core call"
        );
    for expected in ["lt", "gt", "or"] {
        assert!(
            graph
                .blocks
                .iter()
                .flat_map(|b| &b.operations)
                .any(|op| { matches!(&op.kind, OpKind::BinOp { op, .. } if op == expected) }),
            "w_range_iter: missing checked-narrowing {expected} op"
        );
    }
    assert!(
        graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
            matches!(&op.kind, OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } if segments.last().map(String::as_str) == Some("longlongmask"))
        }),
        "w_range_iter: Ok payload must go through longlongmask"
    );
}

/// Minimal `Llbc` carrying only `trait_impls` — the surface
/// [`resolve_trait_assoc_type`] consults.
fn llbc_with_trait_impls(trait_impls: serde_json::Value) -> Llbc {
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [],
            "fun_decls": [],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": trait_impls,
        }
    });
    Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses")
}

/// Two impls bind the associated type differently. A `TraitImpl` ref
/// reads that impl's binding; anything else is not unique.
#[test]
fn trait_assoc_impl_ref_resolves_its_own_binding() {
    let i64_ty = serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}});
    let bool_ty = serde_json::json!({"Scalar": "Bool"});
    let binding = |ty: &serde_json::Value| {
        serde_json::json!({
            "kind": {"TraitType": [0, 0]},
            "skip_binder": {"value": ty}
        })
    };
    let row = |ty: &serde_json::Value| {
        serde_json::json!({
            "impl_trait": {"id": 0, "generics": {"types": []}},
            "types": [binding(ty)],
            "implied_trait_refs": []
        })
    };
    let impl_ref = |id: u64| {
        serde_json::json!({
            "kind": {"TraitImpl": {"id": id, "generics": {"regions": [], "types": [], "const_generics": [], "trait_refs": []}}},
            "trait_decl_ref": {"skip_binder": {"id": 0}}
        })
    };
    let llbc = llbc_with_trait_impls(serde_json::json!([row(&i64_ty), row(&bool_ty)]));
    let assoc = serde_json::json!(0);
    assert_eq!(
        super::resolve_trait_assoc_type_value(&impl_ref(0), &assoc, &llbc),
        Some(&i64_ty)
    );
    assert_eq!(
        super::resolve_trait_assoc_type_value(&impl_ref(1), &assoc, &llbc),
        Some(&bool_ty)
    );
    let clause = serde_json::json!({
        "kind": {"Clause": {"Bound": [0, 0]}},
        "trait_decl_ref": {"skip_binder": {"id": 0}}
    });
    assert_eq!(
        super::resolve_trait_assoc_type_value(&clause, &assoc, &llbc),
        None
    );
}

#[test]
fn map_err_drop_detection_requires_resolved_trait_metadata() {
    use super::{Lowering, Unstructured};
    let span = serde_json::json!({"data": {
        "file_id": 0, "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}
    }});
    let meta = |path: &[&str]| {
        serde_json::json!({
            "name": path.iter().map(|s| serde_json::json!({"Ident": [s, 0]})).collect::<Vec<_>>(),
            "span": span.clone(), "source_text": null,
            "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
            "is_local": true
        })
    };
    for (trait_name, dropless) in [(Some("Drop"), false), (None, false), (Some("Copy"), true)] {
        let traits = trait_name
            .map(|name| {
                vec![serde_json::json!({
                    "def_id": 0, "item_meta": meta(&["core", "ops", "drop", name])
                })]
            })
            .unwrap_or_default();
        let file = serde_json::json!({
            "charon_version": "0.1.201", "has_errors": false,
            "translated": {
                "crate_name": "fixture",
                "type_decls": [{"def_id": 0, "item_meta": meta(&["fixture", "Capture"]), "kind": {"Struct": []}}],
                "fun_decls": [], "global_decls": [], "trait_decls": traits,
                "trait_impls": [{"impl_trait": {"id": 0, "generics": {"types": [
                    {"Value": [1, {"Adt": {"id": 0, "generics": {"regions": [], "types": [], "const_generics": [], "trait_refs": []}}}]}
                ]}}}]
            }
        });
        let llbc = Llbc::from_slice(file.to_string().as_bytes()).unwrap();
        let body: Unstructured = serde_json::from_value(serde_json::json!({
            "locals": {"arg_count": 0, "locals": []}, "body": [], "span": span.clone()
        }))
        .unwrap();
        let dont_look_inside = std::collections::HashSet::new();
        let accum = super::AccumulatorFacts::build(&llbc, &body);
        let tombstoned_leaves = std::collections::HashSet::new();
        let gc_struct_ids_llbc = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
        let lowering = Lowering::new(
            &llbc,
            "fixture".into(),
            &body,
            crate::HostStaticAddrs::default(),
            &[],
            None,
            &dont_look_inside,
            &tombstoned_leaves,
            &gc_struct_ids_llbc,
            super::no_immutable_fields(),
            &std::collections::HashSet::<String>::new(),
            &accum,
            &super::RootStackAnalyzer::new(&llbc, &super::RootStackState::new(&llbc)),
            false,
            false,
        )
        .unwrap();
        assert_eq!(
            lowering.type_decl_is_trivially_dropless(llbc.type_by_id(0).unwrap(), 0),
            dropless,
            "{trait_name:?}"
        );
        assert!(
            !lowering.type_decl_has_explicit_drop(99),
            "an unrelated owner must not be rejected"
        );
    }
}

#[test]
fn zero_sized_fields_are_payload_free_but_mixed_fields_are_not() {
    let span = || {
        serde_json::json!({"data": {
            "file_id": 0,
            "beg": {"line": 1, "col": 0},
            "end": {"line": 1, "col": 1}
        }})
    };
    let item_meta = |name: &str| {
        serde_json::json!({
            "name": [
                {"Ident": ["fixture", 0]},
                {"Ident": [name, 0]}
            ],
            "span": span(),
            "source_text": null,
            "attr_info": {
                "attributes": [],
                "inline": null,
                "rename": null,
                "public": true
            },
            "is_local": true
        })
    };
    let adt = |def_id: u64, hash: u64| {
        serde_json::json!({"Value": [hash, {
            "Adt": {
                "id": def_id,
                "generics": {
                    "regions": [],
                    "types": [],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        }]})
    };
    let field =
        |ty: serde_json::Value| serde_json::json!({"name": null, "ty": ty, "attr_info": null});
    let variant = |name: &str, fields: Vec<serde_json::Value>, discriminant: u64| {
        serde_json::json!({
            "name": name,
            "fields": fields,
            "discriminant": {"Scalar": {"Unsigned": ["U8", discriminant.to_string()]}}
        })
    };
    let layout = |size: u64, field_offsets: Vec<u64>| {
        serde_json::json!([{
            "key": "fixture-target",
            "value": {
                "size": size,
                "align": 1,
                "variant_layouts": [{"field_offsets": field_offsets}],
                "repr": {"transparent": false}
            }
        }])
    };
    let phantom = serde_json::json!({
        "def_id": 0,
        "item_meta": item_meta("Phantom"),
        "kind": {"Struct": []},
        "layout": layout(0, vec![])
    });
    let only_zst = serde_json::json!({
        "def_id": 1,
        "item_meta": item_meta("OnlyZst"),
        "kind": {"Enum": [variant("Value", vec![field(adt(0, 10))], 0)]},
        "layout": layout(1, vec![0])
    });
    let mixed = serde_json::json!({
        "def_id": 2,
        "item_meta": item_meta("Mixed"),
        "kind": {"Enum": [variant(
            "Value",
            vec![
                field(adt(0, 11)),
                field(serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}}))
            ],
            0
        )]},
        "layout": layout(16, vec![0, 8])
    });
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [phantom, only_zst, mixed],
            "fun_decls": [],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": []
        }
    });
    let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
    let phantom_ty = serde_json::from_value::<TyRef>(adt(0, 20)).expect("phantom TyRef");
    let only_zst_ty = serde_json::from_value::<TyRef>(adt(1, 21)).expect("ZST enum TyRef");
    let mixed_ty = serde_json::from_value::<TyRef>(adt(2, 22)).expect("mixed enum TyRef");

    assert!(super::tyref_is_zero_sized(&phantom_ty, &llbc));
    assert!(super::type_decl_is_fieldless_enum(
        llbc.type_by_id(1).expect("OnlyZst declaration"),
        &llbc
    ));
    assert!(!super::type_decl_is_fieldless_enum(
        llbc.type_by_id(2).expect("Mixed declaration"),
        &llbc
    ));
    assert_eq!(
        super::tyref_to_value_type(&only_zst_ty, &llbc),
        ValueType::Int
    );
    assert_eq!(
        super::tyref_to_value_type(&mixed_ty, &llbc),
        ValueType::Ref(Some("Mixed".to_string()))
    );
}

/// A mixed enum (fieldless variants plus a payload-carrying one) is a
/// `SomeInstance` of its interned enum-base classdef, not the untyped
/// `Ref(None)` fallback.  The intern key is the ADT leaf
/// `tyref_class_root` / `Input.class_root` already use, so
/// `getuniqueclassdef_for_struct_root` and `__cast_instance_intrinsic`
/// resolve the same class object the bookkeeper intern's for variant
/// subclasses.  A fieldless-only sibling stays `Int`.
#[test]
fn payload_carrying_enum_paints_typed_ref_of_intern_leaf() {
    let span = || {
        serde_json::json!({"data": {
            "file_id": 0,
            "beg": {"line": 1, "col": 0},
            "end": {"line": 1, "col": 1}
        }})
    };
    let item_meta = |name: &str| {
        serde_json::json!({
            "name": [
                {"Ident": ["fixture", 0]},
                {"Ident": [name, 0]}
            ],
            "span": span(),
            "source_text": null,
            "attr_info": {
                "attributes": [],
                "inline": null,
                "rename": null,
                "public": true
            },
            "is_local": true
        })
    };
    let adt = |def_id: u64, hash: u64| {
        serde_json::json!({"Value": [hash, {
            "Adt": {
                "id": def_id,
                "generics": {
                    "regions": [],
                    "types": [],
                    "const_generics": [],
                    "trait_refs": []
                }
            }
        }]})
    };
    let field = |name: &str, ty: serde_json::Value| serde_json::json!({"name": name, "ty": ty, "attr_info": null});
    let variant = |name: &str, fields: Vec<serde_json::Value>, discriminant: u64| {
        serde_json::json!({
            "name": name,
            "fields": fields,
            "discriminant": {"Scalar": {"Unsigned": ["U8", discriminant.to_string()]}}
        })
    };
    let layout = |size: u64, field_offsets: Vec<u64>| {
        serde_json::json!([{
            "key": "fixture-target",
            "value": {
                "size": size,
                "align": 1,
                "variant_layouts": [{"field_offsets": field_offsets}],
                "repr": {"transparent": false}
            }
        }])
    };
    // Fieldless-only sibling: every variant is payload-free, so the
    // value is the discriminant integer.
    let fieldless = serde_json::json!({
        "def_id": 0,
        "item_meta": item_meta("AccessMode"),
        "kind": {"Enum": [
            variant("ReadWrite", vec![], 0),
            variant("ReadOnly", vec![], 1)
        ]},
        "layout": layout(1, vec![])
    });
    // Mixed: fieldless variants plus one payload-carrying variant.
    // Shape of `Code` (ten unit variants + `Int { signed }`) without
    // naming that enum — the paint is driven by the payload, not the
    // ident.
    let mixed = serde_json::json!({
        "def_id": 1,
        "item_meta": item_meta("Opcode"),
        "kind": {"Enum": [
            variant("Nop", vec![], 0),
            variant("LoadConst", vec![], 1),
            variant(
                "Int",
                vec![field("signed", serde_json::json!({"Scalar": "Bool"}))],
                2
            )
        ]},
        "layout": layout(2, vec![1])
    });
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [fieldless, mixed],
            "fun_decls": [],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": []
        }
    });
    let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
    let fieldless_ty = serde_json::from_value::<TyRef>(adt(0, 10)).expect("fieldless TyRef");
    let mixed_ty = serde_json::from_value::<TyRef>(adt(1, 11)).expect("mixed TyRef");

    assert!(super::type_decl_is_fieldless_enum(
        llbc.type_by_id(0).expect("AccessMode declaration"),
        &llbc
    ));
    assert!(!super::type_decl_is_fieldless_enum(
        llbc.type_by_id(1).expect("Opcode declaration"),
        &llbc
    ));
    assert_eq!(
        super::tyref_to_value_type(&fieldless_ty, &llbc),
        ValueType::Int
    );
    assert_eq!(
        super::tyref_to_value_type(&mixed_ty, &llbc),
        ValueType::Ref(Some("Opcode".to_string())),
        "payload-carrying enum must paint Ref(Some(leaf)), not Ref(None)"
    );
    assert_eq!(
        tyref_to_attr_value_type(&mixed_ty, &llbc),
        ValueType::Ref(Some("Opcode".to_string())),
        "FORCE-attr paint must agree with the value-site paint"
    );
    assert_eq!(
        super::tyref_class_root(&mixed_ty, &llbc).as_deref(),
        Some("Opcode"),
        "intern key must be the Input.class_root leaf"
    );
}

/// `eval::Code` and `module::struct::Code` share a leaf. Harden clears
/// that leaf's origin, and the bare token is not a class. The enum's
/// value must paint the declaration that still has the
/// `__discriminant` row (`module::struct::Code`), while a leaf harden
/// left alone stays bare.
