#[test]
fn range_contains_is_not_harvested_as_function_path() {
    // A bodyless `Range::contains` is not harvested as an opaque
    // external; the FunctionPath stays unregistered (census Skip).
    let llbc = range_contains_fixture();
    let harvested = super::collect_foreign_opaque_method_externals(&llbc);
    assert!(
        !harvested
            .iter()
            .any(|(segments, _, _)| segments.last().map(String::as_str) == Some("contains")),
        "Range::contains must not be harvested: {harvested:?}"
    );
}

#[test]
fn range_contains_lowers_as_method() {
    // Exclusive `Range` is a struct ADT whose FunDecl is Opaque.
    // `impl_method_owner` declines the Method hint for that shape, so
    // the call is a FunctionPath (`Bookkeeper.getdesc`).
    let llbc = range_contains_fixture();
    let graph = super::lower_function(&llbc, "range_contains").expect("lower Range::contains");
    let ops = graph_ops(&graph);
    assert!(
        ops.iter().any(|op| matches!(
            &op.kind,
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                ..
            } if super::fmt_path_ends_with(segments, &["range", "Range", "contains"])
        )),
        "Range::contains must lower as FunctionPath; ops={ops:?}"
    );
}

#[test]
fn same_size_int_bank_transmute_lowers_to_same_as() {
    let llbc = transmute_lowering_fixture();
    let graph = super::lower_function(&llbc, "transmute_u8_to_instruction")
        .expect("lower u8-to-Instruction transmute");
    let ops: Vec<_> = graph
        .blocks
        .iter()
        .flat_map(|block| block.operations.iter())
        .collect();

    assert!(!ops.iter().any(|op| matches!(op.kind, OpKind::Call { .. })));
    assert!(
        ops.iter()
            .all(|op| !matches!(&op.kind, OpKind::UnaryOp { op, .. } if op == "same_as")),
        "same-bank transmute binds the destination to the input"
    );
    let input = ops
        .iter()
        .find_map(|op| match (&op.result, &op.kind) {
            (Some(result), OpKind::Input { name, .. }) if name == "value" => Some(result),
            _ => None,
        })
        .expect("value input");
    let returned = graph
        .blocks
        .iter()
        .find_map(|block| {
            block
                .exits
                .iter()
                .find_map(|link| (link.target == graph.returnblock).then(|| link.args.first()))
        })
        .flatten()
        .and_then(LinkArg::as_variable);
    assert_eq!(returned, Some(input));
}

