fn rhs_defined_by(
    ops: &[&SpaceOperation],
    rhs: &Variable,
    kind_is: impl Fn(&OpKind) -> bool,
) -> bool {
    ops.iter()
        .any(|op| op.result.as_ref() == Some(rhs) && kind_is(&op.kind))
}

