    let ops = graph_ops(&graph);
    assert!(
        ops.iter().any(|op| matches!(
            &op.kind,
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                ..
            } if segments.last().is_some_and(|leaf| leaf == "with_capacity")
        )),
        "Vec::with_capacity must not take the Vec::new retarget; ops={ops:?}"
    );
