/// `fn f<T>(x: &T)` stays generic on the declaration. The call
/// instantiates `T` with a `repr(transparent)` scalar wrapper, so the
/// residual must be refused; the same callee with a non-transparent
/// `T` still lowers.
#[test]
fn generic_residual_borrow_of_transparent_scalar_is_refused() {
    let span = || {
        serde_json::json!({"data": {
            "file_id": 0,
            "beg": {"line": 1, "col": 0},
            "end": {"line": 1, "col": 1}
        }})
    };
    let item_meta = |path: &[&str], is_local: bool| {
        serde_json::json!({
            "name": path
                .iter()
                .map(|segment| serde_json::json!({"Ident": [segment, 0]}))
                .collect::<Vec<_>>(),
            "span": span(),
            "source_text": null,
            "attr_info": {
                "attributes": [],
                "inline": null,
                "rename": null,
                "public": true
            },
            "is_local": is_local
        })
    };
    let struct_decl = |def_id: u64, leaf: &str, transparent: bool| {
        serde_json::json!({
            "def_id": def_id,
            "item_meta": item_meta(&["fixture", leaf], true),
            "kind": {"Struct": [{
                "name": null,
                "ty": {"Scalar": {"Integer": {"Signed": "I64"}}},
                "attr_info": null
            }]},
            "layout": [{
                "key": "fixture-target",
                "value": {
                    "size": 8,
                    "align": 8,
                    "variant_layouts": [{"field_offsets": [0]}],
                    "repr": {"repr_algo": "Rust", "transparent": transparent}
                }
            }]
        })
    };
    let adt = |def_id: u64| {
        serde_json::json!({
            "Adt": {"id": def_id, "generics": {"types": []}}
        })
    };
    let borrowed = |inner: serde_json::Value| serde_json::json!({"Ref": ["_", inner, "Shared"]});
    let type_var = serde_json::json!({"TypeVar": {"Bound": [0, 0]}});
    let unit = serde_json::json!({"Tuple": []});
    let caller = |def_id: u64, name: &str, type_arg: serde_json::Value| {
        let arg_ty = borrowed(type_arg.clone());
        serde_json::json!({
            "def_id": def_id,
            "item_meta": item_meta(&["fixture", name], true),
            "signature": {
                "is_unsafe": false,
                "inputs": [arg_ty.clone()],
                "output": unit.clone()
            },
            "body": {
                "Unstructured": {
                    "span": span(),
                    "locals": {
                        "arg_count": 1,
                        "locals": [
                            {"index": 0, "name": null, "span": span(), "ty": unit.clone()},
                            {"index": 1, "name": "value", "span": span(), "ty": arg_ty.clone()}
                        ]
                    },
                    "body": [
                        {
                            "statements": [],
                            "kind": "Regular",
                            "terminator": {
                                "span": span(),
                                "kind": {
                                    "Call": {
                                        "call": {
                                            "func": {
                                                "Regular": {
                                                    "kind": {"Fun": 2},
                                                    "generics": {
                                                        "regions": [],
                                                        "types": [type_arg],
                                                        "const_generics": [],
                                                        "trait_refs": []
                                                    }
                                                }
                                            },
                                            "args": [{
                                                "Copy": {
                                                    "kind": {"Local": 1},
                                                    "ty": arg_ty.clone()
                                                }
                                            }],
                                            "dest": {"kind": {"Local": 0}, "ty": unit.clone()}
                                        },
                                        "target": 2,
                                        "on_unwind": 1
                                    }
                                }
                            }
                        },
                        {
                            "statements": [],
                            "kind": "Regular",
                            "terminator": {"span": span(), "kind": "UnwindResume"}
                        },
                        {
                            "statements": [],
                            "kind": "Regular",
                            "terminator": {"span": span(), "kind": "Return"}
                        }
                    ]
                }
            }
        })
    };
    let callee = serde_json::json!({
        "def_id": 2,
        "item_meta": item_meta(&["fixture", "f"], false),
        "signature": {
            "is_unsafe": false,
            "inputs": [borrowed(type_var)],
            "output": unit
        },
        "body": "Opaque"
    });
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [
                struct_decl(0, "Word", true),
                struct_decl(1, "Plain", false)
            ],
            "fun_decls": [
                caller(0, "pass_word", adt(0)),
                caller(1, "pass_plain", adt(1)),
                callee
            ],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": []
        }
    });
    let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");

    let refused = super::lower_function(&llbc, "pass_word")
        .expect_err("borrow of a transparent scalar wrapper must be refused");
    let refused = refused.to_string();
    assert!(
        refused.contains("repr(transparent) scalar"),
        "refusal must name the scalar borrow, got {refused}"
    );

    let graph =
        super::lower_function(&llbc, "pass_plain").expect("a non-transparent T must still lower");
    let ops = graph_ops(&graph);
    assert!(
        call_leafs(&ops).iter().any(|leaf| leaf == "f"),
        "non-transparent instantiation must stay a residual call; ops={ops:?}"
    );
}

#[test]
fn atomic_field_layout_string_is_the_inner_scalar() {
    let atomic_decl = |def_id: u64, size: u64| {
        serde_json::json!({
            "def_id": def_id,
            "item_meta": {
                "name": [
                    {"Ident": ["core", 0]},
                    {"Ident": ["sync", 0]},
                    {"Ident": ["atomic", 0]},
                    {"Ident": ["Atomic", 0]}
                ],
                "span": {"data": {
                    "file_id": 0,
                    "beg": {"line": 1, "col": 0},
                    "end": {"line": 1, "col": 8}
                }},
                "source_text": "pub struct Atomic;",
                "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true},
                "is_local": false
            },
            // Opaque: the scalar spelling comes from the `Atomic<T>`
            // type argument, not from reading its storage payload,
            // which a dependency artefact does not carry.
            "kind": "Opaque",
            "layout": [{
                "key": "x86_64-unknown-linux-gnu",
                "value": {
                    "size": size,
                    "align": size,
                    "variant_layouts": [{"field_offsets": [0]}],
                    "repr": {"repr_algo": "Rust", "transparent": false}
                }
            }]
        })
    };
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [
                null,
                atomic_decl(1, 8)
            ],
            "fun_decls": [],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": []
        }
    });
    let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
    let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
    let adt_ty = |def_id: u64, args: serde_json::Value| {
        serde_json::from_value::<super::TyRef>(serde_json::json!({
            "Value": [8, {
                "Adt": {"id": def_id, "generics": {"types": args}}
            }]
        }))
        .expect("fixture TyRef parses")
    };

    // An integer atomic spells as the scalar it is layout-transparent
    // over, so the string-keyed field tables land on the same `Int` the
    // runtime publishes rather than their unknown-name `Ref` wildcard.
    // `AtomicUsize` is the alias `Atomic<usize>`.
    let usize_ty = adt_ty(
        1,
        serde_json::json!([{"Scalar": {"Integer": {"Unsigned": "Usize"}}}]),
    );
    assert_eq!(
        super::tyref_to_field_layout_string(
            &usize_ty,
            &llbc,
            &gc_struct_ids,
            &std::collections::HashSet::<String>::new()
        ),
        "usize"
    );
    assert_eq!(
        crate::codewriter::call::get_type_flag("usize", &std::collections::HashSet::new()).1,
        majit_ir::value::Type::Int
    );

    // `AtomicPtr<T>` (`Atomic<*mut T>`) is a pointer word. Spell it as
    // the actual `*mut T` so fielddescrof does not treat the wrapper as
    // a nested struct, and so a non-GC pointee is not erased to
    // `PyObject`.
    let ptr_ty = adt_ty(
        1,
        serde_json::json!([{"RawPtr": [{"Scalar": {"Integer": {"Unsigned": "U8"}}}, "Mut"]}]),
    );
    let ptr_str = super::tyref_to_field_layout_string(
        &ptr_ty,
        &llbc,
        &gc_struct_ids,
        &std::collections::HashSet::<String>::new(),
    );
    assert_eq!(ptr_str, "*mut u8");
    assert_eq!(
        crate::codewriter::call::get_type_flag(&ptr_str, &std::collections::HashSet::new()).1,
        majit_ir::value::Type::Ref
    );
}

