/// Each receiver that reaches a `Vec` — an inline field, a `&mut Vec`
/// local, and a pointer loaded out of `Box<Vec<_>>` — becomes a getfield
/// of the buffer word. A declared virtualizable array is not a receiver
/// this helper is given: the caller keeps the vable array op.
#[test]
fn vec_index_retargets_each_receiver_shape() {
    use crate::model::{FieldDescriptor, FunctionGraph, OpKind, ValueType, VecFieldPart};

    fn input(graph: &mut FunctionGraph, name: &str) -> crate::flowspace::model::Variable {
        graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: name.into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .expect("input")
    }

    fn field_part(graph: &FunctionGraph, var: &crate::flowspace::model::Variable) -> VecFieldPart {
        graph
            .blocks
            .iter()
            .flat_map(|block| block.operations.iter())
            .find_map(|op| match &op.kind {
                OpKind::FieldRead { field, .. } if op.result.as_ref() == Some(var) => {
                    field.vec_part
                }
                _ => None,
            })
            .expect("vec part")
    }

    let mut inline = FunctionGraph::new("inline_vec_field");
    let frame = input(&mut inline, "frame");
    let stack = inline
        .push_op_var(
            inline.startblock,
            OpKind::FieldRead {
                base: frame,
                field: FieldDescriptor::new("stack", Some("Vm".into())).with_inline_vec(true),
                ty: ValueType::Ref(None),
                pure: false,
            },
            true,
        )
        .expect("stack field");
    let bb = inline.startblock;
    let buf = super::retarget_vec_operand(&mut inline, bb, &stack, VecFieldPart::Buf);
    assert_ne!(buf, stack, "inline field keeps the original read");
    assert!(
        inline
            .blocks
            .iter()
            .flat_map(|block| block.operations.iter())
            .any(|op| {
                matches!(
                    &op.kind,
                    OpKind::FieldRead { field, .. }
                        if op.result.as_ref() == Some(&stack)
                            && field.inline_vec
                            && field.vec_part.is_none()
                )
            }),
        "the shared field read stays the whole Vec"
    );
    assert_eq!(field_part(&inline, &buf), VecFieldPart::Buf);

    let mut local = FunctionGraph::new("vec_local");
    let arg = input(&mut local, "v");
    let bb = local.startblock;
    let buf = super::retarget_vec_operand(&mut local, bb, &arg, VecFieldPart::Buf);
    assert_ne!(buf, arg);
    match &local.blocks[0].operations.last().unwrap().kind {
        OpKind::FieldRead { base, field, .. } => {
            assert_eq!(base, &arg, "&mut Vec local");
            assert_eq!(field.owner_root.as_deref(), Some("alloc::vec::Vec"));
            assert_eq!(field.vec_part, Some(VecFieldPart::Buf));
        }
        other => panic!("local receiver must getfield the buffer, got {other:?}"),
    }

    let mut boxed = FunctionGraph::new("box_vec");
    let frame = input(&mut boxed, "frame");
    let words = boxed
        .push_op_var(
            boxed.startblock,
            OpKind::FieldRead {
                base: frame,
                field: FieldDescriptor::new("operand_words", Some("GrainFrame".into())),
                ty: ValueType::Ref(None),
                pure: false,
            },
            true,
        )
        .expect("box pointer");
    let bb = boxed.startblock;
    let buf = super::retarget_vec_operand(&mut boxed, bb, &words, VecFieldPart::Len);
    assert_ne!(buf, words);
    match &boxed.blocks[0].operations.last().unwrap().kind {
        OpKind::FieldRead { base, field, .. } => {
            assert_eq!(base, &words, "Box<Vec> pointer");
            assert_eq!(field.vec_part, Some(VecFieldPart::Len));
            assert_eq!(field.name, "len");
        }
        other => panic!("box receiver must getfield the length word, got {other:?}"),
    }
}

/// `Vec::set_len` is `l.length = n`. An inline field keeps the owner;
/// a standalone receiver names `alloc::vec::Vec.len` so fielddescrof
/// can attach the Vec SizeDescr (`descr.py` `parent_descr`).
#[test]
fn vec_set_len_write_keeps_the_struct_owner() {
    use crate::model::{FieldDescriptor, FunctionGraph, OpKind, ValueType, VecFieldPart};

    let mut inline = FunctionGraph::new("inline_vec_set_len");
    let frame = inline
        .push_op_var(
            inline.startblock,
            OpKind::Input {
                name: "frame".into(),
                ty: ValueType::Ref(None),
                class_root: None,
            },
            true,
        )
        .expect("frame");
    let stack = inline
        .push_op_var(
            inline.startblock,
            OpKind::FieldRead {
                base: frame.clone(),
                field: FieldDescriptor::new("stack", Some("Vm".into())).with_inline_vec(true),
                ty: ValueType::Ref(None),
                pure: false,
            },
            true,
        )
        .expect("stack");
    let n = inline
        .push_op_var(inline.startblock, OpKind::ConstInt(0), true)
        .expect("n");
    match super::vec_set_len_write(&inline, &stack, n.clone()) {
        Some(OpKind::FieldWrite { base, field, .. }) => {
            assert_eq!(base, frame);
            assert_eq!(field.owner_root.as_deref(), Some("Vm"));
            assert_eq!(field.name, "stack");
            assert_eq!(field.vec_part, Some(VecFieldPart::Len));
        }
        other => panic!("inline set_len must write the owner field, got {other:?}"),
    }

    let mut local = FunctionGraph::new("vec_local_set_len");
    let arg = local
        .push_op_var(
            local.startblock,
            OpKind::Input {
                name: "v".into(),
                ty: ValueType::Ref(None),
                class_root: None,
            },
            true,
        )
        .expect("v");
    assert!(
        super::vec_set_len_write(&local, &arg, n).is_none(),
        "standalone Vec::set_len is not ll_set_length"
    )
}

/// `let v = &mut frame.items; let n = v.len(); v[0]` binds the inline
/// field once. Each use gets its own component read; neither read is
/// stacked on the other.
#[test]
fn shared_inline_vec_len_and_index_keep_the_field_read() {
    use crate::model::{FieldDescriptor, FunctionGraph, OpKind, ValueType, VecFieldPart};

    let mut graph = FunctionGraph::new("shared_inline_vec");
    let frame = graph
        .push_op_var(
            graph.startblock,
            OpKind::Input {
                name: "frame".into(),
                ty: ValueType::Ref(None),
                class_root: None,
            },
            true,
        )
        .expect("frame");
    let v = graph
        .push_op_var(
            graph.startblock,
            OpKind::FieldRead {
                base: frame.clone(),
                field: FieldDescriptor::new("items", Some("Frame".into())).with_inline_vec(true),
                ty: ValueType::Ref(None),
                pure: false,
            },
            true,
        )
        .expect("items");
    let bb = graph.startblock;
    let len = super::retarget_vec_operand(&mut graph, bb, &v, VecFieldPart::Len);
    let elem = super::retarget_vec_operand(&mut graph, bb, &v, VecFieldPart::Buf);
    assert_ne!(len, v);
    assert_ne!(elem, v);
    assert_ne!(len, elem);
    let mut component_bases = Vec::new();
    let mut original_intact = false;
    for op in graph
        .blocks
        .iter()
        .flat_map(|block| block.operations.iter())
    {
        match &op.kind {
            OpKind::FieldRead {
                base, field, ty, ..
            } if op.result.as_ref() == Some(&v) => {
                original_intact = field.inline_vec
                    && field.vec_part.is_none()
                    && field.name == "items"
                    && base == &frame;
                let _ = ty;
            }
            OpKind::FieldRead {
                base, field, ty, ..
            } if op.result.as_ref() == Some(&len) || op.result.as_ref() == Some(&elem) => {
                assert_eq!(
                    base, &frame,
                    "component read uses the struct, not a Vec word"
                );
                assert_eq!(field.name, "items");
                assert!(field.inline_vec);
                assert_ne!(base, &len);
                assert_ne!(base, &elem);
                component_bases.push((field.vec_part, ty.clone()));
            }
            _ => {}
        }
    }
    assert!(
        original_intact,
        "original field read must survive both uses"
    );
    assert_eq!(
        component_bases,
        vec![
            (Some(VecFieldPart::Len), ValueType::Int),
            (Some(VecFieldPart::Buf), ValueType::Ref(None)),
        ]
    );
}

/// `code.varnames.len()` and `code.localspluskinds[i]` share one field
/// read. Each use gets its own fat-pointer word; the shared read is
/// not a `Vec` component and is not rewritten in place.
#[test]
fn fat_box_len_and_index_keep_the_field_read() {
    use crate::flowspace::model::{ConstValue, Constant};
    use crate::model::{FieldDescriptor, FunctionGraph, LinkArg, OpKind, ValueType, VecFieldPart};

    let mut graph = FunctionGraph::new("fat_box_field");
    let code = graph
        .push_op_var(
            graph.startblock,
            OpKind::Input {
                name: "code".into(),
                ty: ValueType::Ref(None),
                class_root: None,
            },
            true,
        )
        .expect("code");
    let varnames = graph
        .push_op_var(
            graph.startblock,
            OpKind::FieldRead {
                base: code.clone(),
                field: FieldDescriptor::new("varnames", Some("bytecode::CodeObject".into())),
                ty: ValueType::Ref(None),
                pure: true,
            },
            true,
        )
        .expect("varnames");
    let marked = vec![varnames.clone()];
    let bb = graph.startblock;
    let len = super::retarget_fat_operand(&mut graph, &marked, bb, &varnames, VecFieldPart::FatLen)
        .expect("same-block len");
    let data =
        super::retarget_fat_operand(&mut graph, &marked, bb, &varnames, VecFieldPart::FatData)
            .expect("same-block data");
    assert_ne!(len, varnames);
    assert_ne!(data, varnames);
    assert_ne!(len, data);
    assert!(
        super::retarget_fat_operand(&mut graph, &marked, bb, &code, VecFieldPart::FatLen).is_none()
    );
    assert!(
        super::retarget_fat_operand(&mut graph, &[], bb, &varnames, VecFieldPart::FatLen).is_none()
    );
    let mut saw_original = false;
    let mut saw_len = false;
    let mut saw_data = false;
    for op in graph
        .blocks
        .iter()
        .flat_map(|block| block.operations.iter())
    {
        let OpKind::FieldRead {
            base, field, ty, ..
        } = &op.kind
        else {
            continue;
        };
        if op.result.as_ref() == Some(&varnames) {
            saw_original = field.vec_part.is_none()
                && !field.inline_vec
                && field.name == "varnames"
                && field.owner_root.as_deref() == Some("bytecode::CodeObject")
                && base == &code;
        } else if op.result.as_ref() == Some(&len) {
            saw_len = field.vec_part == Some(VecFieldPart::FatLen)
                && field.name == "varnames"
                && field.owner_root.as_deref() != Some("alloc::vec::Vec")
                && base == &code
                && matches!(ty, ValueType::Int);
        } else if op.result.as_ref() == Some(&data) {
            saw_data = field.vec_part == Some(VecFieldPart::FatData)
                && base == &code
                && matches!(ty, ValueType::Ref(None));
        }
    }
    assert!(saw_original, "shared field read stays whole");
    assert!(saw_len, "len reads the metadata word");
    assert!(saw_data, "index reads the data word");

    let mut raw_graph = FunctionGraph::new("raw_fat_box");
    let raw_base = raw_graph
        .push_op_var(
            raw_graph.startblock,
            OpKind::Input {
                name: "raw".into(),
                ty: ValueType::Int,
                class_root: None,
            },
            true,
        )
        .expect("raw");
    let raw_box = raw_graph
        .push_op_var(
            raw_graph.startblock,
            OpKind::FieldRead {
                base: raw_base,
                field: FieldDescriptor::new("items", Some("RawOwner".into()))
                    .with_owner_declared_gc(Some(false)),
                ty: ValueType::Int,
                pure: true,
            },
            true,
        )
        .expect("items");
    let start = raw_graph.startblock;
    let raw_data = super::retarget_fat_operand(
        &mut raw_graph,
        &[raw_box.clone()],
        start,
        &raw_box,
        VecFieldPart::FatData,
    )
    .expect("raw data word");
    let raw_ty = raw_graph.blocks.iter().find_map(|block| {
        block.operations.iter().find_map(|op| {
            if op.result.as_ref() != Some(&raw_data) {
                return None;
            }
            match &op.kind {
                OpKind::FieldRead { ty, .. } => Some(ty.clone()),
                _ => None,
            }
        })
    });
    assert!(
        matches!(raw_ty, Some(ValueType::Int)),
        "a raw owner's fat data word is an address"
    );

    let (next, inputs) = graph.create_block_with_arg_vars(1);
    graph.set_goto(graph.startblock, next, vec![varnames.clone()]);
    let hopped =
        super::retarget_fat_operand(&mut graph, &marked, next, &inputs[0], VecFieldPart::FatLen)
            .expect("one phi hop");
    let block = graph.block(next);
    let last = block.operations.last().expect("phi retarget");
    assert_eq!(last.result.as_ref(), Some(&hopped));
    match &last.kind {
        OpKind::FieldRead {
            base, field, ty, ..
        } => {
            assert_eq!(base, &code);
            assert_eq!(field.vec_part, Some(VecFieldPart::FatLen));
            assert_eq!(field.name, "varnames");
            assert!(matches!(ty, ValueType::Int));
        }
        other => panic!("phi copy must retarget, got {other:?}"),
    }

    let mut other = FunctionGraph::new("fat_const_phi");
    let (merge, merge_inputs) = other.create_block_with_arg_vars(1);
    other.set_goto_mixed(
        other.startblock,
        merge,
        vec![LinkArg::Const(Constant::new(ConstValue::Int(1)))],
    );
    let dummy = other.alloc_value_var();
    assert!(
        super::retarget_fat_operand(
            &mut other,
            &[dummy],
            merge,
            &merge_inputs[0],
            VecFieldPart::FatLen,
        )
        .is_none(),
        "a constant phi is not a fat field"
    );
}

/// The `Vec` index fold must accept a `usize` index.
///
/// `usize` types as `Unsigned`, not `Int`, so gating on `Int` alone left
/// both the read and write lifts dead for every real callsite — caught
/// only by the `#[ignore]`d real-LLBC anchor
/// (`vec_index_mut_fill_user_function_args_real`), which does not run in
/// CI.  This pins the acceptance set without the 440MB corpus.
#[test]
fn vec_index_gate_accepts_both_integer_banks_and_rejects_range() {
    let llbc = llbc_with_trait_impls(serde_json::json!([]));
    let ty = |v: serde_json::Value| {
        serde_json::from_value::<super::TyRef>(serde_json::json!({
            "Value": [0, v]
        }))
        .expect("fixture TyRef parses")
    };
    let usize_ty = ty(serde_json::json!({"Scalar": {"Integer": {"Unsigned": "Usize"}}}));
    assert_eq!(
        super::tyref_to_value_type(&usize_ty, &llbc),
        crate::model::ValueType::Unsigned,
        "usize must type as Unsigned — the trap this gate fell into"
    );
    let gc_struct_ids = super::harvest_declared_gc_facts(&llbc).gc_struct_ids();
    assert!(
        super::vec_index_type_is_scalar(
            &usize_ty,
            &llbc,
            &gc_struct_ids,
            &std::collections::HashSet::<String>::new()
        ),
        "Vec index fold must accept a usize index"
    );
    assert!(
        super::vec_index_type_is_scalar(
            &ty(serde_json::json!({"Scalar": {"Integer": {"Signed": "I64"}}})),
            &llbc,
            &gc_struct_ids,
            &std::collections::HashSet::<String>::new()
        ),
        "Vec index fold must accept a signed index"
    );
    assert!(
        !super::vec_index_type_is_scalar(
            &ty(serde_json::json!({ "Adt": { "id": 7  } })),
            &llbc,
            &gc_struct_ids,
            &std::collections::HashSet::<String>::new()
        ),
        "a Range index types as Ref and must stay rejected"
    );
}

#[test]
fn trait_assoc_type_resolves_via_unique_impl() {
    // `C::Name` with `impl Trait#1 for X { type Name = bool }` as
    // the LLBC's only impl of trait 1 renders the bound type.
    let llbc = llbc_with_trait_impls(serde_json::json!([
        null,
        {
            "impl_trait": { "id": 1 },
            "types": [{
                "kind": { "TraitType": [1, 0] },
                "skip_binder": { "value": { "Scalar": "Bool" } }
            }]
        }
    ]));
    let projection = serde_json::json!({
        "TraitType": [
            { "trait_decl_ref": { "skip_binder": { "id": 1 } } },
            0,
            { "regions": [], "types": [], "const_generics": [], "trait_refs": [] }
        ]
    });
    assert_eq!(
        charon_type_value_to_ast_string(&projection, &llbc, 0),
        "bool"
    );
}

#[test]
fn trait_assoc_type_keeps_fallback_when_impl_ambiguous_or_missing() {
    // Two impls of trait 1 → instantiation-dependent → fallback.
    let two_impls = llbc_with_trait_impls(serde_json::json!([
        {
            "impl_trait": { "id": 1 },
            "types": [{
                "kind": { "TraitType": [1, 0] },
                "skip_binder": { "value": { "Scalar": "Bool" } }
            }]
        },
        {
            "impl_trait": { "id": 1 },
            "types": [{
                "kind": { "TraitType": [1, 0] },
                "skip_binder": { "value": { "Scalar": "Char" } }
            }]
        }
    ]));
    let projection = serde_json::json!({
        "TraitType": [
            { "trait_decl_ref": { "skip_binder": { "id": 1 } } },
            0,
            { "regions": [], "types": [], "const_generics": [], "trait_refs": [] }
        ]
    });
    assert_eq!(
        charon_type_value_to_ast_string(&projection, &two_impls, 0),
        "??TraitType"
    );
    // No impl at all → fallback too.
    let no_impls = llbc_with_trait_impls(serde_json::json!([]));
    assert_eq!(
        charon_type_value_to_ast_string(&projection, &no_impls, 0),
        "??TraitType"
    );
}

