#[test]
fn pointer_to_usize_cast_keeps_rpython_signed_then_unsigned_sequence() {
    let mut graph = FunctionGraph::new("test");
    let entry = graph.startblock;
    let ptr = graph
        .push_op_var(entry, OpKind::ConstRefAddr(0x1000), true)
        .expect("pointer value");

    let (retype, result) = push_ptr_to_unsigned_cast(&mut graph, entry, ptr.clone());
    graph
        .block_mut(entry)
        .operations
        .push(crate::model::SpaceOperation {
            result: Some(result.clone()),
            kind: retype,
        });

    let ops = &graph.block(entry).operations;
    let (signed, signed_arg) = match &ops[1] {
        crate::model::SpaceOperation {
            result: Some(signed),
            kind:
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    args,
                    result_ty: ValueType::Int,
                },
        } if segments.last().map(String::as_str) == Some("cast_ptr_to_int") => (signed, &args[0]),
        other => panic!("first cast must be Signed cast_ptr_to_int: {other:?}"),
    };
    assert_eq!(signed_arg, &ptr);
    match &ops[2] {
        crate::model::SpaceOperation {
            result: Some(actual_result),
            kind:
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    args,
                    result_ty: ValueType::Unsigned,
                },
        } if segments.last().map(String::as_str) == Some("r_uint") => {
            assert_eq!(actual_result, &result);
            assert_eq!(&args[0], signed);
        }
        other => panic!("second cast must retype to Unsigned with r_uint: {other:?}"),
    }
}

/// `fn as usize` is Int-banked (`history.getkind` of `Ptr(FuncType)`),
/// but `rbuiltin.py gen_cast` still starts from a Ptr origin: Signed
/// `cast_ptr_to_int` then `r_uint`. A bare `r_uint` is the integer
/// signedness flip and fails rtyping (`PtrRepr` to `IntegerRepr`).
#[test]
fn fn_ptr_as_usize_emits_cast_ptr_to_int_then_r_uint() {
    let span = serde_json::json!({
        "data": {
            "file_id": 0,
            "beg": {"line": 1, "col": 0},
            "end": {"line": 1, "col": 1}
        }
    });
    let fn_ptr = serde_json::json!({
        "FnPtr": {
            "skip_binder": {
                "inputs": [],
                "output": {
                    "Adt": {
                        "id": 0,
                        "builtin": "Tuple",
                        "generics": {"types": []}
                    }
                },
                "is_unsafe": false
            }
        }
    });
    let usize_ty = serde_json::json!({"Scalar": {"Integer": {"Unsigned": "Usize"}}});
    let place = |index: u64, ty: &serde_json::Value| serde_json::json!({"kind": {"Local": index}, "ty": ty});
    let local = |index: u64, ty: &serde_json::Value| {
        serde_json::json!({
            "index": index,
            "name": null,
            "span": span,
            "ty": ty
        })
    };
    let caller = serde_json::json!({
        "def_id": 0,
        "item_meta": {
            "name": [
                {"Ident": ["fixture", 0]},
                {"Ident": ["fn_as_usize", 0]}
            ],
            "span": span,
            "source_text": null,
            "attr_info": {
                "attributes": [],
                "inline": null,
                "rename": null,
                "public": true
            },
            "is_local": true
        },
        "signature": {
            "is_unsafe": false,
            "inputs": [fn_ptr.clone()],
            "output": usize_ty.clone()
        },
        "body": {"Unstructured": {
            "span": span,
            "locals": {"arg_count": 1, "locals": [
                local(0, &usize_ty),
                local(1, &fn_ptr)
            ]},
            "body": [{
                "statements": [{
                    "span": span,
                    "kind": {"Assign": [
                        place(0, &usize_ty),
                        {"UnaryOp": [
                            {"Cast": {"Scalar": [fn_ptr.clone(), usize_ty.clone()]}},
                            {"Copy": place(1, &fn_ptr)}
                        ]}
                    ]}
                }],
                "kind": "Regular",
                "terminator": {"span": span, "kind": "Return"}
            }]
        }}
    });
    let file = serde_json::json!({
        "charon_version": "0.1.201",
        "has_errors": false,
        "translated": {
            "crate_name": "fixture",
            "type_decls": [],
            "fun_decls": [caller],
            "global_decls": [],
            "trait_decls": [],
            "trait_impls": []
        }
    });
    let llbc = Llbc::from_slice(file.to_string().as_bytes()).expect("fixture Llbc parses");
    let graph = super::lower_function(&llbc, "fn_as_usize").expect("lower fn_as_usize");

    let calls: Vec<_> = graph
        .blocks
        .iter()
        .flat_map(|block| &block.operations)
        .filter_map(|op| match &op.kind {
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                args,
                result_ty,
            } => Some((
                segments.last().map(String::as_str),
                op.result.as_ref(),
                args.as_slice(),
                result_ty,
            )),
            _ => None,
        })
        .collect();
    let cast_idx = calls
        .iter()
        .position(|(leaf, _, _, _)| *leaf == Some("cast_ptr_to_int"))
        .expect("fn as usize emits cast_ptr_to_int");
    let retype_idx = calls
        .iter()
        .position(|(leaf, _, _, _)| *leaf == Some("r_uint"))
        .expect("fn as usize emits r_uint");
    assert_eq!(
        retype_idx,
        cast_idx + 1,
        "rbuiltin.py gen_cast is cast_ptr_to_int then r_uint, got {calls:?}"
    );
    let (_, signed, cast_args, cast_ty) = &calls[cast_idx];
    assert_eq!(**cast_ty, ValueType::Int);
    let (_, result, retype_args, retype_ty) = &calls[retype_idx];
    assert_eq!(**retype_ty, ValueType::Unsigned);
    assert_eq!(
        retype_args.first().and_then(LinkArg::as_variable),
        signed.as_deref(),
        "r_uint retypes the Signed cast_ptr_to_int result"
    );
    assert!(result.is_some());
    assert_eq!(cast_args.len(), 1);
}

