/// `func.__module__`: a free function's module ends at its leaf, a
/// method's at its impl segment, and the crate stays on the path.
#[test]
#[ignore]
fn fundecl_module_is_the_crate_qualified_defining_module() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-module.ullbc"
    );
    let llbc = Llbc::load(path).expect("load real LLBC");
    let module_of = |name: &str| {
        let fd = llbc
            .iter_local_fns()
            .find(|fd| fd.item_meta.name_path() == name)
            .unwrap_or_else(|| panic!("no fun decl {name}"));
        super::fundecl_module(fd)
    };
    assert_eq!(
        module_of("pyre_module::module::unicodedata::interp_ucd::char_and_default").as_deref(),
        Some("pyre_module::module::unicodedata::interp_ucd")
    );
    let method = llbc
        .iter_local_fns()
        .find(|fd| {
            fd.item_meta
                .name_path()
                .starts_with("pyre_module::module::")
                && fd
                    .item_meta
                    .name
                    .iter()
                    .any(|seg| matches!(seg, NameSeg::Other(_)))
        })
        .expect("a method under pyre_module::module");
    let module = super::fundecl_module(method).expect("method module");
    let name_path = method.item_meta.name_path();
    assert!(
        name_path.starts_with(&format!("{module}::<")),
        "{name_path}: module {module} must end at the impl segment"
    );
}

/// `args.get(1..).unwrap_or(&[])` is Rust's checked spelling of PyPy's
/// ordinary `args[1:]`.  Keep `get`'s Option semantics in a `start <= len`
/// diamond and materialize the successful payload as the deferred
/// `getslice(start, None)` marker.
#[test]
#[ignore]
fn slice_get_rangefrom_lowers_to_a_guarded_getslice() {
    use crate::model::{CallTarget, OpKind};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-module.ullbc"
    );
    let llbc = Llbc::load(path).expect("load real LLBC");
    let name = "pyre_module::module::unicodedata::interp_ucd::ucd_method_args";
    let graph =
        super::lower_function(&llbc, name).unwrap_or_else(|err| panic!("lower {name}: {err:?}"));
    assert!(
            !graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
                matches!(&op.kind, OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                    if segments == &["core", "slice", "<Impl>", "get"])
            }),
            "{name}: RangeFrom slice get must not survive as an opaque core call"
        );
    assert!(
            graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
                matches!(&op.kind, OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                    if segments == &["__getslice_rangefrom"])
            }),
            "{name}: successful get arm must carry the deferred getslice"
        );
    assert!(
        graph
            .blocks
            .iter()
            .flat_map(|b| &b.operations)
            .any(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "le")),
        "{name}: RangeFrom get must guard start <= len"
    );
}

/// Native constant slice bounds must retain their actual rtyper provenance
/// when simplification removes a forwarding block input.
#[test]
#[ignore]
fn slice_get_rangefrom_preserves_constant_bound_rtype() {
    use crate::translator::rtyper::call_registry::CallRegistry;
    use crate::translator::rtyper::cutover::{DualGateOutcome, dual_gate_check_with_registry};
    let llbc = Llbc::load(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-module.ullbc"
    ))
    .expect("load real LLBC");
    let graph = super::lower_function(
        &llbc,
        "pyre_module::module::unicodedata::interp_ucd::ucd_method_args",
    )
    .expect("lower actual RangeFrom get caller");
    let program = super::build_semantic_program_from_llbcs_with_static_addrs_and_function_names(
        &[llbc],
        crate::HostStaticAddrs::default(),
        &[],
        &["ucd_method_args"],
    )
    .expect("derive actual native registry metadata");
    let bk = std::rc::Rc::new(crate::annotator::bookkeeper::Bookkeeper::new());
    bk.set_struct_fields(std::rc::Rc::new(program.struct_fields));
    bk.set_enum_variant_by_discriminant(std::rc::Rc::new(program.enum_variant_by_discriminant));
    let registry = CallRegistry::new(bk);
    let result = dual_gate_check_with_registry(
        &graph,
        &registry,
        &crate::codewriter::call::GraphStore::default(),
    )
    .expect("dual gate must not error");
    let DualGateOutcome::Match { real_constants, .. } = result else {
        panic!("{result:?}");
    };
    let bound = graph
        .blocks
        .iter()
        .flat_map(|b| &b.operations)
        .find_map(|op| match &op.kind {
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                args,
                ..
            } if segments == &["__getslice_rangefrom"] => Some(args[1].clone()),
            _ => None,
        })
        .expect("actual live slice bound");
    use crate::translator::rtyper::lltypesystem::lltype::LowLevelType;
    assert_eq!(real_constants.get(&bound), Some(&LowLevelType::Unsigned));
    bound.set_concretetype(None);
    crate::codewriter::type_state::apply_from_flowspace_constants(&real_constants);
    assert_eq!(bound.concretetype(), Some(LowLevelType::Unsigned));
}

#[test]
#[ignore]
fn native_load_fast_preserves_unit_operand_rtype() {
    let llbc = Llbc::load(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-interpreter.ullbc"
    ))
    .expect("load real LLBC");
    let graph = super::lower_function(&llbc, "pyre_interpreter::pyopcode::execute_load_fast")
        .expect("lower native load_fast");
    let mut checked = 0;
    for block in &graph.blocks {
        for arg in block.exits.iter().flat_map(|link| &link.args) {
            let crate::model::LinkArg::Value(var) = arg else {
                continue;
            };
            if crate::model::FunctionGraph::concretetype_of(var) != crate::model::ConcreteType::Void
            {
                continue;
            }
            checked += 1;
            assert!(
                block.inputargs.contains(var)
                    || block.operations.iter().any(|op| {
                        op.result.as_ref() == Some(var) && matches!(op.kind, OpKind::ConstNone)
                    }),
                "unit edge operand {var:?} has no definition in {:?}",
                block.id
            );
        }
    }
    assert!(
        checked > 0,
        "fixture must exercise actual unit-valued edges"
    );
}

/// `bytearrayobject.py` `descr_repr` appends three values for a non-printable
/// byte — `'\\x'` and the two nibble characters.  The expansion consumed
/// the template's `\x` piece as a match condition only, so a JIT-compiled
/// repr rendered `bytearray(b'ff')` where CPython renders
/// `bytearray(b'\xff')`.  Assert the literal is emitted and folded first.
#[test]
fn lower_hex_byte_02_expansion_emits_the_backslash_x_literal() {
    use crate::model::{CallTarget, ConcreteType, FunctionGraph, OpKind};
    let mut graph = FunctionGraph::new("t");
    let value = graph.alloc_value_var_with_type(ConcreteType::Unknown);
    let result = graph.alloc_value_var_with_type(ConcreteType::Unknown);
    let pieces = vec!["\\x".to_string(), String::new()];
    let ops = super::emit_lower_hex_byte_02_ops(&mut graph, &pieces, &value, result.clone());

    let literal = ops
            .iter()
            .find(|op| {
                matches!(&op.kind, OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                    if segments.first().is_some_and(|s| s == "__str_const")
                        && segments.get(1).is_some_and(|s| s == "\\x"))
            })
            .expect("the template's leading `\\x` must be emitted, not only matched");
    let literal = literal.result.clone().expect("__str_const has a result");

    // `'\\x'` is upstream's FIRST buf.append, so it must be the left
    // operand of the first concat.
    let first_add = ops
        .iter()
        .find(|op| matches!(&op.kind, OpKind::BinOp { op, .. } if op == "add"))
        .expect("the parts fold through add");
    let OpKind::BinOp { lhs, .. } = &first_add.kind else {
        unreachable!("matched an add above")
    };
    assert_eq!(lhs.id(), literal.id(), "`\\x` must be concatenated first");

    assert_eq!(
        ops.last().and_then(|op| op.result.clone()).map(|v| v.id()),
        Some(result.id()),
        "the final op must reuse the displaced format result var"
    );
}

use serde_json::{Value, json};

fn str_builder_span() -> Value {
    json!({"data": {"file_id": 0,
            "beg": {"line": 1, "col": 0}, "end": {"line": 1, "col": 1}}})
}

fn str_builder_generics() -> Value {
    json!({"regions": [], "types": [], "const_generics": [], "trait_refs": []})
}

fn ident_seg(name: &str) -> Value {
    json!({"Ident": [name, 0]})
}

fn str_builder_meta(path: Vec<Value>, is_local: bool) -> Value {
    json!({
        "name": path,
        "span": str_builder_span(),
        "source_text": null,
        "is_local": is_local,
        "attr_info": {"attributes": [], "inline": null, "rename": null, "public": true}
    })
}

fn wtf8_adt() -> Value {
    json!({"Adt": {"id": 0, "generics": str_builder_generics()}})
}

fn outcome_adt() -> Value {
    json!({"Adt": {"id": 1, "generics": str_builder_generics()}})
}

fn ref_wtf8(kind: &str) -> Value {
    json!({"Ref": [{"Erased": null}, wtf8_adt(), kind]})
}

fn unit_ty() -> Value {
    json!({"Adt": {"id": 0, "builtin": "Tuple", "generics": str_builder_generics()}})
}

fn word_ty() -> Value {
    json!({"Scalar": {"Integer": {"Unsigned": "U64"}}})
}

