/// `mini_buffer_params` constructs `Option<(*mut u8, usize)>`.  The Rust
/// payload is inline, but the translator gives the internal aggregate one
/// GC-managed `Tuple<...>` class identity; the per-instantiation `Some`
/// row must therefore be seeded with that same identity before any shared
/// `InstanceRepr` can cache the variant layout.
#[test]
#[ignore]
fn mini_buffer_params_preregisters_tuple_payload_row() {
    use crate::annotator::model::SomeValue;
    use crate::model::{CallTarget, OpKind};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-interpreter.ullbc"
    );
    let llbc = Llbc::load(path).expect("load real interpreter LLBC");
    let program = super::build_semantic_program_from_llbcs_with_static_addrs_and_function_names(
        std::slice::from_ref(&llbc),
        crate::HostStaticAddrs::default(),
        &["module::_cffi_backend::cbuffer"],
        &["mini_buffer_params", "call_once"],
    )
    .expect("build mini_buffer_params semantic program");
    assert!(
        program
            .functions
            .iter()
            .any(|function| function.name == "mini_buffer_params"),
        "mini_buffer_params semantic function"
    );
    let tuple_owner = program
        .functions
        .iter()
        .flat_map(|function| &function.graph().blocks)
        .flat_map(|block| &block.operations)
        .find_map(|op| match &op.kind {
            OpKind::Call {
                target: CallTarget::SyntheticTransparentCtor { name, .. },
                ..
            } if name == "Tuple<*mut u8,usize>" => Some(name.clone()),
            _ => None,
        })
        .expect("concrete tuple aggregate class");

    let (variant_owner, rows) = program
        .struct_fields
        .fields
        .iter()
        .find(|(owner, _)| owner.ends_with("Option<(*mut u8,usize)>::Some"))
        .expect("concrete Option<tuple>::Some registry row");
    assert_eq!(
        rows,
        &vec![("__pos_0".to_string(), "(*mut u8,usize)".to_string())],
        "the concrete tuple payload must not fall back to the ??T template"
    );
    let variant_owner = variant_owner.clone();

    let bk = std::rc::Rc::new(crate::annotator::bookkeeper::Bookkeeper::new());
    bk.set_struct_fields(std::rc::Rc::new(program.struct_fields));
    bk.set_enum_variant_by_discriminant(std::rc::Rc::new(program.enum_variant_by_discriminant));
    for root in bk.struct_root_names() {
        bk.getuniqueclassdef_for_struct_root(&root)
            .expect("project struct root");
    }
    bk.pre_register_enum_variant_classes();

    let enum_root = variant_owner
        .strip_suffix("::Some")
        .expect("Some-qualified owner");
    let variant = bk
        .getuniqueclassdef_for_enum_variant(enum_root, "Some")
        .expect("resolve pre-registered Some classdef");
    let variant = variant.borrow();
    let Some(SomeValue::Instance(payload)) = variant.attrs.get("__pos_0").map(|attr| &attr.s_value)
    else {
        panic!(
            "Some.__pos_0 must carry the concrete tuple class, got {:?}",
            variant.attrs.get("__pos_0").map(|attr| &attr.s_value)
        )
    };
    assert_eq!(
        payload
            .classdef
            .as_ref()
            .expect("tuple payload classdef")
            .borrow()
            .name,
        tuple_owner,
        "the pre-registered payload and constructor must share one class"
    );
    assert!(
        !variant.attrs["__pos_0"].readonly,
        "the constructor payload must be an instance field before repr setup"
    );
}

/// PyPy's `instantiate(W_IntObject)` is lowered to a real allocation plus
/// `intval` store, never left as the Rust helper that accepted the
/// stack-built aggregate.  The real LLBC constructor must therefore leave
/// this frontend with `NewWithVtable`, not residual `malloc_typed`.
#[test]
#[ignore]
fn w_int_new_fuses_typed_allocation() {
    use crate::model::{CallTarget, OpKind};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-object.ullbc"
    );
    let llbc = Llbc::load(path).expect("load real LLBC");
    let graph = super::lower_function_with_static_addrs(
        &llbc,
        "pyre_object::intobject::w_int_new",
        crate::HostStaticAddrs {
            pytypes: &[("pyobject::INT_TYPE", 0x1020_3040)],
            ..crate::HostStaticAddrs::default()
        },
    )
    .expect("lower w_int_new");
    assert!(
        graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
            matches!(&op.kind, OpKind::NewWithVtable { owner, .. }
                    if owner.ends_with("W_IntObject"))
        }),
        "w_int_new must lower instantiate(W_IntObject) to NewWithVtable: {graph:#?}"
    );
    assert!(
        !graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
            matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } if segments.last().map(String::as_str) == Some("malloc_typed")
            )
        }),
        "w_int_new must not retain residual malloc_typed: {graph:#?}"
    );
}

/// PyPy's rStringIO and buffered I/O implementations use ordinary
/// `buffer[start:end]` list slices. The Rust port spells those as a
/// `SliceIndex<Range<usize>>` call, which must recover RPython's direct
/// `getslice` operation without adding a non-upstream dominator proof.
#[test]
#[ignore]
fn pypy_buffer_ranges_lower_to_getslice() {
    use crate::model::{CallTarget, OpKind};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-interpreter.ullbc"
    );
    let llbc = Llbc::load(path).expect("load real LLBC");
    for fname in ["read_bytes", "parse_length_prefixed_protocols"] {
        let graph = super::lower_function(&llbc, fname)
            .unwrap_or_else(|err| panic!("lower {fname}: {err}"));
        assert!(
                !graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
                    matches!(&op.kind, OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if super::fmt_path_ends_with(segments, &["core", "slice", "index", "<Impl>", "index"]))
                }),
                "{fname}: PyPy list slice must not remain an opaque Rust index"
            );
        assert!(
                graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
                    matches!(&op.kind, OpKind::Call { target: CallTarget::FunctionPath { segments, .. }, .. }
                        if segments == &["__getslice_range".to_string()])
                }),
                "{fname}: Range slice must use the RPython getslice marker"
            );
    }
}

/// `forwarded_exporter` uses
/// `W_PickleBuffer::from_obj(obj).map(|pb| -> Result<_, PyError> { ... })`.
/// The closure graph follows the uniform Result exception ABI, while
/// `Option::map` must retain that Result as data inside `Some`; anchor the
/// late synthesized call to the ordinary catch-and-rewrap caller rule.
#[test]
#[ignore]
fn forwarded_exporter_map_rewraps_scoped_result() {
    use crate::model::{CallTarget, ExitSwitch, OpKind};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-interpreter.ullbc"
    );
    let llbc = Llbc::load(path).expect("load real LLBC");
    // `lower_function`'s default host table names NO error carrier, and
    // the carrier is what `tyref_is_result_of_carrier` compares `E`
    // against — with the default the closure's `Result<*mut PyObject,
    // PyError>` is not a scoped result, `call_once_result_exc` stays
    // `None`, and the rewrap this test grades can never be reached.
    // Pass the same spec `pyre-jit-trace`'s prepass installs.
    let graph = super::lower_function_with_static_addrs(
        &llbc,
        "forwarded_exporter",
        crate::HostStaticAddrs {
            error_carrier: crate::ErrorCarrierSpec {
                carrier_path: "pyre_interpreter::error::PyError",
                carrier_class: "",
                carrier_wrappers: &[],
                to_exc_object: Some(&["pyre_interpreter", "error", "pyerror_to_exc_object"]),
                from_exc_object: Some(("PyError", "from_exc_object")),
            },
            ..crate::HostStaticAddrs::default()
        },
    )
    .expect("lower forwarded_exporter");

    let call_block = graph
        .blocks
        .iter()
        .find(|block| {
            block.operations.iter().any(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call {
                        target: CallTarget::Method { name, .. },
                        ..
                    } if name == "call_once"
                )
            })
        })
        .expect("Option::map closure call_once block");
    assert!(
        matches!(call_block.exitswitch, Some(ExitSwitch::LastException)),
        "the Result-returning closure call must expose normal/exception successors"
    );
    for variant in ["Ok", "Err"] {
        assert_eq!(
            graph
                .blocks
                .iter()
                .flat_map(|block| &block.operations)
                .filter(|op| matches!(
                    &op.kind,
                    OpKind::Call {
                        target: CallTarget::SyntheticTransparentCtor { name, .. },
                        ..
                    } if name == variant
                ))
                .count(),
            1,
            "the caller must rebuild one Result::{variant} shell"
        );
    }
}

/// PyPy's `_IOBase.writelines_w` receives `self` directly from the
/// gateway and raises on a missing receiver.  The Rust gateway spells the
/// same boundary as `args.first().copied().ok_or_else(...)?`; after the
/// combined lowering neither the foreign Option combinator nor the Result
/// `?` shell may survive, and the niladic closure's error must terminate on
/// the graph exception edge.
#[test]
#[ignore]
fn iobase_writelines_ok_or_else_try_is_value_or_exception() {
    use crate::model::{CallTarget, OpKind};
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/llbc/pyre-interpreter.ullbc"
    );
    let llbc = Llbc::load(path).expect("load real LLBC");
    let graph = super::lower_function_with_static_addrs(
        &llbc,
        "iobase_writelines",
        crate::HostStaticAddrs {
            error_carrier: crate::ErrorCarrierSpec {
                carrier_path: "pyre_interpreter::error::PyError",
                carrier_class: "",
                carrier_wrappers: &[],
                to_exc_object: Some(&["pyre_interpreter", "error", "pyerror_to_exc_object"]),
                from_exc_object: Some(("PyError", "from_exc_object")),
            },
            ..crate::HostStaticAddrs::default()
        },
    )
    .expect("lower iobase_writelines");

    assert!(
        !graph.blocks.iter().flat_map(|b| &b.operations).any(|op| {
            matches!(
                &op.kind,
                OpKind::Call {
                    target: CallTarget::Method { name, .. },
                    ..
                } if name == "ok_or_else"
            )
        }),
        "the foreign Option::ok_or_else residual must be gone"
    );
    let error_arm = graph
        .blocks
        .iter()
        .find(|block| {
            block.operations.iter().any(|op| {
                matches!(
                    &op.kind,
                    OpKind::Call {
                        target: CallTarget::Method { name, .. },
                        ..
                    } if name == "call_once"
                )
            })
        })
        .expect("the None arm calls its error closure");
    assert!(
        error_arm
            .exits
            .iter()
            .any(|link| link.target == graph.exceptblock),
        "the None arm must raise through the native graph exception edge"
    );
}

